        #region Initialization

        private void OnServerInitialized()
        {
            if (config == null)
            {
                config = PluginConfig.DefaultConfig();
                SaveConfig();
            }

            IQKits = plugins.Find("IQKits");
            BetterChat = plugins.Find("BetterChat");
            ColouredChat = plugins.Find("ColouredChat");
            PlayerRankings = plugins.Find("PlayerRankings");
            PrivateMessages = plugins.Find("PrivateMessages");
            if (IQKits == null)
                PrintWarning("[InfoMenu] IQKits не найден при запуске. Меню китов будет ждать загрузку IQKits.");

            LoadData();
            RegisterImages();
            RegisterStatIcons();

            foreach (var command in config.Commands.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                if (!string.IsNullOrEmpty(command))
                    cmd.AddChatCommand(command.TrimStart('/'), this, nameof(CmdOpen));
            }

            foreach (var player in BasePlayer.activePlayerList.ToList())
            {
                HandleConnection(player);
                EnsureRankTracking(player);
            }

            timer.Every(60f, UpdateActiveTimeAndRanks);
        }

        private void OnPluginLoaded(Plugin plugin)
        {
            if (plugin == null)
                return;

            if (string.Equals(plugin.Name, "IQKits", StringComparison.OrdinalIgnoreCase))
            {
                IQKits = plugin;
                PrintWarning("[InfoMenu] IQKits подключён: " + plugin.Version);
            }
            else if (string.Equals(plugin.Name, "BetterChat", StringComparison.OrdinalIgnoreCase)) BetterChat = plugin;
            else if (string.Equals(plugin.Name, "ColouredChat", StringComparison.OrdinalIgnoreCase)) ColouredChat = plugin;
            else if (string.Equals(plugin.Name, "PlayerRankings", StringComparison.OrdinalIgnoreCase)) PlayerRankings = plugin;
            else if (string.Equals(plugin.Name, "PrivateMessages", StringComparison.OrdinalIgnoreCase)) PrivateMessages = plugin;
            else if (string.Equals(plugin.Name, "ImageLibrary", StringComparison.OrdinalIgnoreCase))
            {
                ImageLibrary = plugin;
                RegisterImages();
                RegisterStatIcons();
            }
        }

        private Plugin GetIQKitsPlugin()
        {
            if (IQKits == null)
                IQKits = plugins.Find("IQKits");

            return IQKits;
        }

        private void RegisterImages()
        {
            if (ImageLibrary == null)
            {
                PrintWarning("ImageLibrary не найден. Изображения меню будут пропущены.");
                return;
            }

            string[] images =
            {
                config.BackgroundImage,
                config.BannerImage,
                config.ShopIcon,
                config.DiscordIcon,
                config.VkIcon,
                config.TelegramIcon,
                config.SteamIcon,
                config.DiscordQr,
                config.VkQr,
                config.TelegramQr,
                config.SteamQr
            };

            foreach (string url in images)
            {
                if (!string.IsNullOrEmpty(url))
                    ImageLibrary.Call("AddImage", url, url, 0UL);
            }

            // QR магазина загружаем отдельным ключом и только после загрузки
            // перерисовываем уже открытое меню. Иначе ImageLibrary может ещё
            // не успеть скачать PNG, и Rust показывает знак вопроса.
            string shopQrUrl = string.IsNullOrEmpty(config.ShopQr) ? DefaultShopQrUrl : config.ShopQr;

            if (!string.IsNullOrEmpty(shopQrUrl))
            {
                ImageLibrary.Call(
                    "AddImage",
                    shopQrUrl,
                    ShopQrImageKey,
                    0UL,
                    (Action)(() =>
                    {
                        foreach (BasePlayer online in BasePlayer.activePlayerList.ToList())
                        {
                            if (online == null || !online.IsConnected || !openMenuPlayers.Contains(online.userID))
                                continue;

                            timer.Once(0.05f, () =>
                            {
                                if (online != null && online.IsConnected && openMenuPlayers.Contains(online.userID))
                                    OpenMenu(online, 0);
                            });
                        }
                    })
                );
            }
        }

        private void RegisterStatIcons()
        {
            if (ImageLibrary == null || statIcons == null)
                return;

            foreach (var entry in statIcons)
            {
                try
                {
                    string imageName = "MetalicRustStats_1to1_" + entry.Key;
                    byte[] data = Convert.FromBase64String(entry.Value);

                    // Кладём PNG непосредственно в ImageLibrary, без внешних URL.
                    // Уникальное имя не конфликтует с другими плагинами/иконками.
                    ImageLibrary.Call("AddImageData", imageName, data, 0UL);
                }
                catch (Exception ex)
                {
                    PrintWarning("[InfoMenu] Не удалось добавить иконку статистики в ImageLibrary: " + entry.Key + " | " + ex.Message);
                }
            }

            if (statItemIconUrls != null)
            {
                foreach (var entry in statItemIconUrls)
                {
                    try
                    {
                        string imageName = "MetalicRustStats_Item_" + entry.Key;
                        ImageLibrary.Call("AddImage", entry.Value, imageName);
                    }
                    catch (Exception ex)
                    {
                        PrintWarning("[InfoMenu] Не удалось добавить предметную иконку в ImageLibrary: " + entry.Key + " | " + ex.Message);
                    }
                }
            }
        }

        private void Unload()
        {
            foreach (var player in BasePlayer.activePlayerList.ToList())
                DestroyMenu(player);

            pendingKitTakes.Clear();
            redeemedKitKeys.Clear();
            failedKitKeys.Clear();
            lastInventoryFullKit.Clear();
            openKitPages.Clear();
            openShopCategories.Clear();
            activeSideCommands.Clear();
            gameStorePurchasesInProgress.Clear();
            pendingShopConfirmations.Clear();
            SaveData();
        }

        private void OnPlayerConnected(BasePlayer player)
        {
            HandleConnection(player);
            EnsureRankTracking(player);

        }

        private void OnPlayerDisconnected(BasePlayer player)
        {
            if (player == null)
                return;

            openKitPages.Remove(player.userID);
            gameStorePurchasesInProgress.Remove(player.userID);
            pendingShopConfirmations.Remove(player.userID);
            activeSideCommands.Remove(player.userID);
            pendingKitTakes.Remove(player.userID);
            lastInventoryFullKit.Remove(player.userID);
        }

        private void HandleConnection(BasePlayer player)
        {
            if (player == null || !config.OpenOnConnection)
                return;

            if (config.FirstConnectionOnly)
            {
                if (players.ContainsKey(player.userID))
                    return;

                players[player.userID] = new PlayerData { FirstSeen = true };

                timer.Once(1f, () =>
                {
                    if (player != null && player.IsConnected)
                        OpenMenu(player, 0);
                });
            }
            else
            {
                timer.Once(1f, () =>
                {
                    if (player != null && player.IsConnected)
                        OpenMenu(player, 0);
                });
            }
        }

