        private readonly List<GameStoreProduct> gameStoreProducts = new List<GameStoreProduct>
        {
            new GameStoreProduct("VIP", "АВТОМАТИЧЕСКАЯ ВЫДАЧА", GameStoreVipUrl, 350, "vip", "", 7),
            new GameStoreProduct("PREMIUM", "АВТОМАТИЧЕСКАЯ ВЫДАЧА", GameStorePremiumUrl, 500, "premium", "", 7),
            new GameStoreProduct("ELITE", "АВТОМАТИЧЕСКАЯ ВЫДАЧА", GameStoreEliteUrl, 750, "elite", "", 7),
            new GameStoreProduct("СКИНЫ", "", GameStoreSkinsUrl, 100, "", "grantperm %STEAMID% skinbox.use 14d", 14),
            new GameStoreProduct("КОПТЕР", "ЗАБРАТЬ В КИТАХ", GameStoreCoptersUrl, 30, "", "", 0)
        };

        private int GetShopProductCategory(GameStoreProduct product)
        {
            if (product == null)
                return 0;

            if (!string.IsNullOrEmpty(product.Group))
                return 1; // ПРИВИЛЕГИИ: VIP / PREMIUM / ELITE

            if (string.Equals(product.Title, "СКИНЫ", StringComparison.OrdinalIgnoreCase))
                return 2; // СКИНЫ

            if (string.Equals(product.Title, "КОПТЕР", StringComparison.OrdinalIgnoreCase))
                return 3; // КОПТЕР

            return 0;
        }

        private void OpenShopPage(BasePlayer player)
        {
            if (player == null || !player.IsConnected)
                return;

            // Магазин является частью обычного InfoMenu, а не отдельным окном.
            // Сохраняем боковое меню, верхние вкладки и кнопку закрытия.
            OpenMenu(player, 0);
            CuiHelper.DestroyUi(player, MainLayer + ".Content");

            var container = new CuiElementContainer();
            string content = MainLayer + ".Content";
            string shopLayer = MainLayer + ".Content.GameStore";

            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0", FadeIn = 0.22f },
                RectTransform = { AnchorMin = "0.195 0.045", AnchorMax = "0.985 0.895" }
            }, MainLayer + ".Main", content);

            container.Add(new CuiPanel
            {
                Image = { Color = ParseColor(config.CardColor), FadeIn = 0.16f },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }
            }, content, shopLayer);

            AddText(container, shopLayer, "МАГАЗИН", 22, TextAnchor.UpperLeft,
                config.TextColor, "0.035 0.90", "0.45 0.98", "ShopTitle");
            AddText(container, shopLayer,
                "ТОВАРЫ METALICRUST • GAMESTORES", 10, TextAnchor.UpperLeft,
                config.SecondaryTextColor, "0.037 0.84", "0.70 0.90", "ShopSubtitle");

            // Верхние кнопки магазина находятся внутри основной области InfoMenu.

            // Один фиксированный CUI-элемент баланса. AddText использует GUID,
            // поэтому для динамического баланса нужен постоянный Name.
            string balanceLayer = shopLayer + ".Balance";
            AddNamedText(container, shopLayer, "БАЛАНС: ЗАГРУЗКА...", 14, TextAnchor.MiddleLeft,
                config.GreenColor, "0.39 0.835", "0.80 0.895",
                shopLayer + ".GameStoreBalanceText");

            container.Add(new CuiButton
            {
                Button =
                {
                    Command = "infomenu.shop topup",
                    Color = ParseColor(config.GreenColor),
                    HighlightedColor = ParseColor(config.ButtonHoverColor)
                },
                Text =
                {
                    Text = "ПОПОЛНИТЬ БАЛАНС",
                    Font = config.Font,
                    FontSize = 10,
                    Align = TextAnchor.MiddleCenter,
                    Color = "0.02 0.04 0.02 1"
                },
                RectTransform = { AnchorMin = "0.81 0.835", AnchorMax = "0.995 0.895" }
            }, shopLayer, balanceLayer + ".TopUp");

            RequestGameStoreBalance(player, shopLayer);

            // Категории — только навигация внутри магазина. Реальные товары ниже.
            string[] categories = { "ВСЕ", "ПРИВИЛЕГИИ", "СКИНЫ", "КОПТЕРЫ" };
            for (int i = 0; i < categories.Length; i++)
            {
                float xMin = 0.025f + i * 0.18f;
                float xMax = xMin + 0.17f;
                int selectedCategory = 0;
                if (openShopCategories.ContainsKey(player.userID))
                    selectedCategory = Mathf.Clamp(openShopCategories[player.userID], 0, categories.Length - 1);
                bool selected = i == selectedCategory;

                container.Add(new CuiButton
                {
                    Button =
                    {
                        Command = "infomenu.shop category " + i,
                        Color = selected ? ParseColor(config.GreenColor) : "0.22 0.24 0.24 1",
                        HighlightedColor = ParseColor(config.ButtonHoverColor)
                    },
                    Text =
                    {
                        Text = categories[i],
                        Font = config.Font,
                        FontSize = 10,
                        Align = TextAnchor.MiddleCenter,
                        Color = selected ? "0.02 0.04 0.02 1" : "0.9 0.9 0.9 1"
                    },
                    RectTransform =
                    {
                        AnchorMin = string.Format(CultureInfo.InvariantCulture, "{0:0.###} 0.755", xMin),
                        AnchorMax = string.Format(CultureInfo.InvariantCulture, "{0:0.###} 0.815", xMax)
                    }
                }, shopLayer);
            }

            // Товары распределяются по категориям:
            // ВСЕ — все товары; ПРИВИЛЕГИИ — VIP/PREMIUM/ELITE;
            // СКИНЫ — только скины; КОПТЕРЫ — только коптер.
            int selectedCategoryForProducts = 0;
            if (openShopCategories.ContainsKey(player.userID))
                selectedCategoryForProducts = Mathf.Clamp(openShopCategories[player.userID], 0, 3);

            List<int> visibleProductIndices = new List<int>();
            for (int productIndex = 0; productIndex < gameStoreProducts.Count; productIndex++)
            {
                GameStoreProduct product = gameStoreProducts[productIndex];
                if (product != null &&
                    (selectedCategoryForProducts == 0 ||
                     GetShopProductCategory(product) == selectedCategoryForProducts))
                {
                    visibleProductIndices.Add(productIndex);
                }
            }

            int columns = 3;
            int rows = Mathf.Max(1, Mathf.CeilToInt(visibleProductIndices.Count / (float)columns));
            float left = 0.025f;
            float right = 0.975f;
            float top = 0.735f;
            float bottom = 0.08f;
            float gapX = 0.018f;
            float gapY = 0.025f;
            float cardW = (right - left - gapX * (columns - 1)) / columns;
            float availableHeight = top - bottom;
            float cardH = Mathf.Min(0.30f, (availableHeight - gapY * (rows - 1)) / rows);

            for (int visibleIndex = 0; visibleIndex < visibleProductIndices.Count; visibleIndex++)
            {
                int i = visibleProductIndices[visibleIndex];
                GameStoreProduct product = gameStoreProducts[i];
                int col = visibleIndex % columns;
                int row = visibleIndex / columns;
                float xMin = left + col * (cardW + gapX);
                float xMax = xMin + cardW;
                float yMax = top - row * (cardH + gapY);
                float yMin = yMax - cardH;
                string card = shopLayer + ".Product." + i;

                container.Add(new CuiPanel
                {
                    Image = { Color = ParseColor(config.MainPanelColor) },
                    RectTransform =
                    {
                        AnchorMin = string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###}", xMin, yMin),
                        AnchorMax = string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###}", xMax, yMax)
                    }
                }, shopLayer, card);

                container.Add(new CuiPanel
                {
                    Image = { Color = "0.18 0.20 0.20 1" },
                    RectTransform = { AnchorMin = "0.025 0.29", AnchorMax = "0.975 0.96" } }
                , card, card + ".Image");

                AddText(container, card + ".Image", product.Title, 18, TextAnchor.MiddleCenter,
                    config.GreenColor, "0.05 0.05", "0.95 0.95", "ProductImagePlaceholder");

                AddText(container, card, product.Title, 15, TextAnchor.MiddleLeft,
                    config.TextColor, "0.045 0.17", "0.58 0.28", "ProductName");
                if (!string.IsNullOrEmpty(product.Description))
                    AddText(container, card, product.Description, 9, TextAnchor.MiddleLeft,
                        config.SecondaryTextColor, "0.045 0.08", "0.65 0.17", "ProductDescription");
                AddText(container, card, GetShopDurationLabel(player, product), 13, TextAnchor.UpperRight,
                    config.GreenColor, "0.80 0.82", "0.96 0.96", "ProductDuration");
                AddText(container, card, product.Price.ToString(CultureInfo.InvariantCulture) + " ₽", 13, TextAnchor.MiddleRight,
                    config.GreenColor, "0.50 0.08", "0.65 0.18", "ProductPrice");

                // Для КОПТЕРА таймер повторной покупки полностью отключён.
                // Для остальных товаров сохраняется существующая логика ограничений.
                long shopCooldown = GetShopRemainingCooldown(player, product);
                if (shopCooldown > 0L)
                {
                    AddShopCountdown(container, card, shopCooldown);
                }
                else
                {
                    container.Add(new CuiButton
                    {
                        Button =
                        {
                            Command = "infomenu.shop buy " + i,
                            Color = ParseColor(config.GreenColor),
                            HighlightedColor = ParseColor(config.ButtonHoverColor)
                        },
                        Text =
                        {
                            Text = "КУПИТЬ",
                            Font = config.Font,
                            FontSize = 11,
