        private void OpenGameStoreProduct(BasePlayer player, int index)
        {
            if (player == null || !player.IsConnected)
                return;

            if (index < 0 || index >= gameStoreProducts.Count)
            {
                OpenShopPage(player);
                return;
            }

            GameStoreProduct product = gameStoreProducts[index];
            if (product == null || product.Price <= 0)
                return;

            if (GetShopRemainingCooldown(player, product) > 0L)
                return;

            pendingShopConfirmations[player.userID] = index;
            ShowShopPurchaseConfirmation(player, product, index);
        }

