        private void OpenReportPage(BasePlayer player, int page, string search = null)
        {
            if (player == null || !player.IsConnected)
                return;

            const int perPage = 28;
            string query = (search ?? string.Empty).Trim();
            List<BasePlayer> targets = BasePlayer.activePlayerList
                .Where(x => x != null && x.IsConnected && x != player)
                .Where(x => string.IsNullOrEmpty(query)
                    || (x.displayName != null && x.displayName.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0)
                    || x.userID.ToString().IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0)
                .OrderBy(x => x.displayName ?? string.Empty, StringComparer.OrdinalIgnoreCase)
                .ToList();

            int pageCount = Math.Max(1, (int)Math.Ceiling(targets.Count / (double)perPage));
            page = Mathf.Clamp(page, 0, pageCount - 1);

            OpenMenu(player, 0);
            CuiHelper.DestroyUi(player, MainLayer + ".Content");

            var container = new CuiElementContainer();
            string content = MainLayer + ".Content";

            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0", FadeIn = 0.22f },
                RectTransform = { AnchorMin = "0.195 0.045", AnchorMax = "0.985 0.895" }
            }, MainLayer + ".Main", content);

            string layer = ReportLayer;
            container.Add(new CuiPanel
            {
                Image = { Color = "0.10 0.11 0.12 0.97" },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }
            }, content, layer);

            HighlightSideButton(container, "report");

            container.Add(new CuiButton
            {
                Button = { Command = "infomenu.report.close", Color = "0.88 0.04 0.10 1", HighlightedColor = "1 0.15 0.15 1" },
                Text = { Text = "✕  ЗАКРЫТЬ", Font = config.Font, FontSize = 14, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                RectTransform = { AnchorMin = "0.875 0.915", AnchorMax = "0.975 0.975" }
            }, layer);

            int start = page * perPage;
            int end = Math.Min(start + perPage, targets.Count);

            const float left = 0.015f;
            const float colGap = 0.010f;
            const float colWidth = 0.2425f;
            const float rowGap = 0.010f;
            const float rowHeight = 0.092f;
            const float top = 0.935f;

            for (int i = start; i < end; i++)
            {
                int n = i - start;
                int col = n % 4;
                int row = n / 4;
                float xMin = left + col * (colWidth + colGap);
                float xMax = xMin + colWidth;
                float yTop = top - row * (rowHeight + rowGap);
                float yBottom = yTop - rowHeight;
                BasePlayer target = targets[i];
                string rowId = layer + ".Player." + target.userID;

                container.Add(new CuiPanel
                {
                    Image = { Color = "0.16 0.17 0.18 1" },
                    RectTransform =
                    {
                        AnchorMin = string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###}", xMin, yBottom),
                        AnchorMax = string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###}", xMax, yTop)
                    }
                }, layer, rowId);

                // Заглушка аватара оставлена как в эталонном рабочем файле:
                // она не зависит от Steam API и всегда отображается.
                container.Add(new CuiPanel
                {
                    Image = { Color = "0.08 0.09 0.10 1" },
                    RectTransform = { AnchorMin = "0.015 0.12", AnchorMax = "0.18 0.88" }
                }, rowId, rowId + ".AvatarBg");
                AddText(container, rowId + ".AvatarBg", "?", 22, TextAnchor.MiddleCenter,
                    "0.85 0.85 0.85 1", "0 0", "1 1", rowId + ".Avatar");

                AddText(container, rowId, EscapeText(target.displayName ?? "UNKNOWN"), 12, TextAnchor.UpperLeft,
                    config.TextColor, "0.205 0.52", "0.83 0.91", rowId + ".Name");
                AddText(container, rowId, target.userID.ToString(), 9, TextAnchor.UpperLeft,
                    config.SecondaryTextColor, "0.205 0.18", "0.83 0.50", rowId + ".Id");

                container.Add(new CuiButton
                {
                    Button = { Command = "infomenu.report.send " + target.userID, Color = "0.25 0.27 0.29 1", HighlightedColor = ParseColor(config.GreenColor) },
                    Text = { Text = "▶", Font = config.Font, FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                    RectTransform = { AnchorMin = "0.875 0.20", AnchorMax = "0.97 0.80" }
                }, rowId);
            }

            // Нижняя строка — поиск и легенда, как на фото.
            container.Add(new CuiPanel
            {
                Image = { Color = "0.13 0.14 0.15 1" },
                RectTransform = { AnchorMin = "0.015 0.015", AnchorMax = "0.355 0.075" }
            }, layer, layer + ".SearchBg");

            container.Add(new CuiElement
            {
                Parent = layer + ".SearchBg",
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = query,
                        Font = config.Font,
                        FontSize = 11,
                        Align = TextAnchor.MiddleLeft,
                        Color = "0.85 0.85 0.85 1",
                        CharsLimit = 32,
                        NeedsKeyboard = true,
                        Command = "infomenu.report.search"
                    },
                    new CuiRectTransformComponent { AnchorMin = "0.03 0", AnchorMax = "0.84 1" }
                }
            });

            container.Add(new CuiButton
            {
                Button = { Command = "infomenu.report.search", Color = ParseColor(config.GreenColor), HighlightedColor = ParseColor(config.ButtonHoverColor) },
                Text = { Text = "⌕", Font = config.Font, FontSize = 20, Align = TextAnchor.MiddleCenter, Color = "0 0 0 1" },
                RectTransform = { AnchorMin = "0.84 0", AnchorMax = "1 1" }
            }, layer + ".SearchBg");

            AddText(container, layer, "✓ - ИГРОК ПРОВЕРЯЛСЯ 1 РАЗ", 9, TextAnchor.MiddleLeft,
                config.SecondaryTextColor, "0.365 0.015", "0.53 0.075", "ReportLegend1");
            AddText(container, layer, "✓ - ИГРОК ПРОВЕРЯЛСЯ НЕСКОЛЬКО РАЗ", 9, TextAnchor.MiddleLeft,
                config.GreenColor, "0.535 0.015", "0.79 0.075", "ReportLegend2");

            container.Add(new CuiButton
            {
                Button = { Command = "infomenu.report " + Math.Max(0, page - 1), Color = page > 0 ? "0.25 0.27 0.29 1" : "0.12 0.13 0.14 1", HighlightedColor = ParseColor(config.ButtonHoverColor) },
                Text = { Text = "◀", Font = config.Font, FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "0.8 0.8 0.8 1" },
                RectTransform = { AnchorMin = "0.80 0.015", AnchorMax = "0.845 0.075" }
            }, layer);

            AddText(container, layer,
                string.Format(CultureInfo.InvariantCulture, "{0}-{1}", targets.Count == 0 ? 0 : start + 1, end),
                10, TextAnchor.MiddleCenter, config.SecondaryTextColor,
                "0.845 0.015", "0.945 0.075", "ReportPages");

            container.Add(new CuiButton
            {
                Button = { Command = "infomenu.report " + Math.Min(page + 1, pageCount - 1), Color = page < pageCount - 1 ? "0.25 0.27 0.29 1" : "0.12 0.13 0.14 1", HighlightedColor = ParseColor(config.ButtonHoverColor) },
                Text = { Text = "▶", Font = config.Font, FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "0.8 0.8 0.8 1" },
                RectTransform = { AnchorMin = "0.945 0.015", AnchorMax = "0.985 0.075" }
            }, layer);

            CuiHelper.AddUi(player, container);
        }

        private void HighlightSideButton(CuiElementContainer container, string command)
        {
            if (config == null || config.SideButtons == null)
                return;

            float top = 0.845f;
            const float height = 0.055f;
            const float gap = 0.014f;

            for (int i = 0; i < config.SideButtons.Count; i++)
            {
                SideButton button = config.SideButtons[i];
                if (button == null) continue;
                float bottom = top - height;
                if (bottom < 0.045f) break;
                if (!string.Equals(button.Command, command, StringComparison.OrdinalIgnoreCase))
                {
                    top = bottom - gap;
                    continue;
                }

                container.Add(new CuiButton
                {
                    Button = { Command = "infomenu.side " + i, Color = ParseColor(config.GreenColor), HighlightedColor = ParseColor(config.GreenColor) },
                    Text = { Text = button.Title ?? "", Font = config.Font, FontSize = config.ButtonFontSize, Align = TextAnchor.MiddleCenter, Color = "0 0 0 1" },
                    RectTransform = { AnchorMin = string.Format(CultureInfo.InvariantCulture, "0.055 {0:0.###}", bottom), AnchorMax = string.Format(CultureInfo.InvariantCulture, "0.945 {0:0.###}", top) }
                }, MainLayer + ".Side", MainLayer + ".Side.Selected." + command);
                return;
            }
        }

        private void OpenStatisticsPage(BasePlayer player, int tab)
        {
            if (player == null || !player.IsConnected)
                return;

            if (tab == 1 || tab == 2)
            {
                OpenStatisticsTopPage(player, tab == 1, 0, string.Empty);
                return;
            }

            // Статистика является страницей внутри того же InfoMenu.
            // Левая колонка НЕ уничтожается и НЕ создаётся заново.
            OpenMenu(player, 0, false);

            // В эталоне сверху нет обычных вкладок Информация/Команды/Бинды/Правила.
            // Вместо них оставляем верхнюю область под уведомление о наградах.
            CuiHelper.DestroyUi(player, MainLayer + ".Top");
            CuiHelper.DestroyUi(player, MainLayer + ".Content");

            var c = new CuiElementContainer();
            string content = MainLayer + ".Content";
            string layer = MainLayer + ".Content.Statistics";
            PlayerData data = GetPlayerData(player);
            RankProgress progress = GetRankProgress(player);
            if (data == null) data = new PlayerData();
            if (progress == null) progress = new RankProgress();

            // Верхняя полоса как на образце.
            c.Add(new CuiPanel
            {
                Image = { Color = "0.36 0.16 0.13 0.96" },
                RectTransform = { AnchorMin = "0.175 0.90", AnchorMax = "0.64 1" }
            }, MainLayer + ".Main", MainLayer + ".StatsRewardBar");
            AddText(c, MainLayer + ".StatsRewardBar",
                "Награды топ 3 игроков за вайп зафиксированы!",
                13, TextAnchor.MiddleLeft, "1 0.72 0.20 1",
                "0.10 0", "0.98 1", "RewardText");

            // Контент строго в правой части главного InfoMenu, как на фото.
            c.Add(new CuiPanel
            {
                Image = { Color = "0.10 0.11 0.12 0.98" },
                RectTransform = { AnchorMin = "0.195 0.045", AnchorMax = "0.985 0.895" }
            }, MainLayer + ".Main", content);
            c.Add(new CuiPanel
            {
                Image = { Color = "0.10 0.11 0.12 1" },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }
            }, content, layer);

            HighlightSideButton(c, "top");

