        private void OpenStatisticsTopPage(BasePlayer player, bool wipe, int page, string query)
        {
            if (player == null || !player.IsConnected)
                return;

            // Открываем ТОП внутри существующего InfoMenu.
            // Левая колонка не пересоздаётся и не изменяется.
            OpenMenu(player, 0, false);
            CuiHelper.DestroyUi(player, MainLayer + ".Content");

            var c = new CuiElementContainer();
            string content = MainLayer + ".Content";
            string layer = MainLayer + ".Content.Statistics";

            AddStatisticsShell(c, layer, wipe ? "wipe" : "all");

            // -------------------------------------------------
            // ВЕРХНЯЯ ПАНЕЛЬ — внутри существующего окна.
            // -------------------------------------------------
            AddStatTab(c, layer, "СТАТИСТИКА ИГРОКА",
                "0.015 0.905", "0.265 0.965", false,
                "infomenu.stats player");

            AddStatTab(c, layer, "ТОП ЗА ВАЙП",
                "0.265 0.905", "0.455 0.965", wipe,
                "infomenu.stats wipe 0");

            AddStatTab(c, layer, "ТОП ЗА ВСЕ ВРЕМЯ",
                "0.455 0.905", "0.690 0.965", !wipe,
                "infomenu.stats all 0");

            // Оранжевый баннер наград показывается ОДИНАКОВО в ТОП ЗА ВАЙП
            // и в ТОП ЗА ВСЕ ВРЕМЯ. Он находится внутри самого InfoMenu.
            // Баннер полностью такой же, как в разделе «СТАТИСТИКА ИГРОКА».
            c.Add(new CuiPanel
            {
                Image = { Color = "0.36 0.16 0.13 0.96" },
                RectTransform = { AnchorMin = "0.175 0.90", AnchorMax = "0.64 1" }
            }, MainLayer + ".Main", MainLayer + ".StatsRewardBar");
            AddText(c, MainLayer + ".StatsRewardBar",
                "Награды топ 3 игроков за вайп зафиксированы!",
                13, TextAnchor.MiddleLeft, "1 0.72 0.20 1",
                "0.10 0", "0.98 1", "RewardText");

            // Кнопка закрытия в правом верхнем углу.
            c.Add(new CuiButton
            {
                Button =
                {
                    Command = "infomenu.close",
                    Color = "0.83 0.18 0.18 1",
                    HighlightedColor = "0.95 0.25 0.25 1"
                },
                Text =
                {
                    Text = "✕  ЗАКРЫТЬ",
                    Font = config.Font,
                    FontSize = 10,
                    Align = TextAnchor.MiddleCenter,
                    Color = "1 1 1 1"
                },
                RectTransform = { AnchorMin = "0.885 0.905", AnchorMax = "0.985 0.965" }
            }, layer);

            // -------------------------------------------------
            // ДАННЫЕ
            // -------------------------------------------------
            List<ulong> ids = players.Keys.ToList();

            if (!string.IsNullOrWhiteSpace(query))
            {
                string q = query.Trim();
                ids = ids.Where(id =>
                {
                    PlayerData d;
                    if (!players.TryGetValue(id, out d))
                        return false;

                    BasePlayer online = BasePlayer.FindByID(id);
                    string name = online != null ? online.displayName : id.ToString();

                    return id.ToString().Contains(q) ||
                           (!string.IsNullOrEmpty(name) &&
                            name.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0);
                }).ToList();
            }

            ids = ids.OrderByDescending(id =>
            {
                PlayerData d;
                if (!players.TryGetValue(id, out d))
                    return 0d;

                return wipe ? GetWipePoints(d) : GetStatPoints(d);
            }).ThenBy(id => id).ToList();

            const int perPage = 10;
            int pageCount = Math.Max(1, (ids.Count + perPage - 1) / perPage);
            page = Mathf.Clamp(page, 0, pageCount - 1);

            int startIndex = page * perPage;
            int endIndex = Math.Min(startIndex + perPage, ids.Count);

            // -------------------------------------------------
            // ЗАГОЛОВОК ТАБЛИЦЫ
            // -------------------------------------------------
            DrawTopHeader(c, layer, wipe);

            // -------------------------------------------------
            // СТРОКИ
            // -------------------------------------------------
            const float rowTop = 0.735f;
            const float rowHeight = 0.050f;
            const float rowStep = 0.054f;

            for (int i = startIndex; i < endIndex; i++)
            {
                ulong id = ids[i];
                PlayerData d = players[id];

                int place = i + 1;
                float yTop = rowTop - (i - startIndex) * rowStep;
                float yBottom = yTop - rowHeight;

                DrawTopRow(c, layer, id, d, place, wipe, yBottom, yTop);
            }

            // -------------------------------------------------
            // ПОИСК
            // -------------------------------------------------
            string searchBg = layer + ".Search";

            c.Add(new CuiPanel
            {
                Image = { Color = "0.18 0.19 0.20 1" },
                RectTransform = { AnchorMin = "0.015 0.035", AnchorMax = "0.385 0.095" }
            }, layer, searchBg);

            c.Add(new CuiElement
            {
                Parent = searchBg,
                Components =
                {
                    new CuiInputFieldComponent
                    {
                        Text = query ?? "",
                        FontSize = 9,
                        Align = TextAnchor.MiddleLeft,
                        Color = ParseColor(config.TextColor),
                        Command = "infomenu.stats.search " + (wipe ? "wipe" : "all") + " "
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0.03 0",
                        AnchorMax = "0.83 1"
                    }
                }
            });

            c.Add(new CuiButton
            {
                Button =
                {
                    Command = "infomenu.stats.search " + (wipe ? "wipe" : "all") + " ",
                    Color = ParseColor(config.GreenColor),
                    HighlightedColor = ParseColor(config.ButtonHoverColor)
                },
                Text =
                {
                    Text = "⌕",
                    Font = config.Font,
                    FontSize = 16,
                    Align = TextAnchor.MiddleCenter,
                    Color = "0 0 0 1"
                },
                RectTransform = { AnchorMin = "0.83 0", AnchorMax = "1 1" }
            }, searchBg);

            // -------------------------------------------------
            // ПАГИНАЦИЯ
            // -------------------------------------------------
            c.Add(new CuiButton
            {
                Button =
                {
                    Command = "infomenu.stats " + (wipe ? "wipe" : "all") + " " + Math.Max(0, page - 1),
                    Color = page > 0 ? "0.23 0.24 0.25 1" : "0.12 0.13 0.14 1",
                    HighlightedColor = ParseColor(config.ButtonHoverColor)
                },
                Text =
                {
                    Text = "‹",
                    Font = config.Font,
                    FontSize = 17,
                    Align = TextAnchor.MiddleCenter,
                    Color = "1 1 1 1"
                },
                RectTransform = { AnchorMin = "0.795 0.035", AnchorMax = "0.835 0.095" }
            }, layer);

            // Для реального количества строк показываем диапазон текущей страницы.
            string range = ids.Count == 0
                ? "0 - 0"
                : string.Format(CultureInfo.InvariantCulture,
                    "{0} - {1}", startIndex + 1, endIndex);

            AddText(c, layer,
                range,
                10,
                TextAnchor.MiddleCenter,
                config.SecondaryTextColor,
                "0.835 0.035",
                "0.945 0.095",
                "StatsPages");

            c.Add(new CuiButton
            {
                Button =
                {
                    Command = "infomenu.stats " + (wipe ? "wipe" : "all") + " " + Math.Min(page + 1, pageCount - 1),
                    Color = page < pageCount - 1 ? "0.23 0.24 0.25 1" : "0.12 0.13 0.14 1",
                    HighlightedColor = ParseColor(config.ButtonHoverColor)
                },
                Text =
                {
                    Text = "›",
                    Font = config.Font,
                    FontSize = 17,
                    Align = TextAnchor.MiddleCenter,
                    Color = "1 1 1 1"
                },
                RectTransform = { AnchorMin = "0.945 0.035", AnchorMax = "0.985 0.095" }
            }, layer);

            CuiHelper.AddUi(player, c);
        }

