        private void DrawTopRow(CuiElementContainer c, string parent, ulong id, PlayerData d, int place, bool wipe, float yBottom, float yTop)
        {
            string row = parent + ".Row." + id;

            // Чередование строк: плотная тёмная таблица.
            string rowColor = (place % 2 == 0)
                ? "0.20 0.21 0.22 1"
                : "0.16 0.17 0.18 1";

            c.Add(new CuiPanel
            {
                Image = { Color = rowColor },
                RectTransform =
                {
                    AnchorMin = "0.015 " + yBottom.ToString("0.###", CultureInfo.InvariantCulture),
                    AnchorMax = "0.985 " + yTop.ToString("0.###", CultureInfo.InvariantCulture)
                }
            }, parent, row);

            string name = id.ToString();
            BasePlayer online = BasePlayer.FindByID(id);
            if (online != null && !string.IsNullOrEmpty(online.displayName))
                name = online.displayName;

            // Место + медаль для первых трёх мест.
            if (place <= 3)
            {
                string medalColor = place == 1
                    ? "1 0.72 0.12 1"
                    : place == 2
                        ? "0.80 0.82 0.84 1"
                        : "0.80 0.48 0.20 1";

                c.Add(new CuiPanel
                {
                    Image = { Color = medalColor },
                    RectTransform = { AnchorMin = "0.010 0.25", AnchorMax = "0.027 0.75" }
                }, row, row + ".Medal");

                AddText(c, row + ".Medal",
                    place.ToString(CultureInfo.InvariantCulture),
                    7,
                    TextAnchor.MiddleCenter,
                    "0.05 0.05 0.05 1",
                    "0 0", "1 1", "Number");
            }
            else
            {
                AddText(c, row,
                    place.ToString(CultureInfo.InvariantCulture),
                    9,
                    TextAnchor.MiddleCenter,
                    config.TextColor,
                    "0 0", "0.045 1", "Place");
            }

            AddText(c, row,
                EscapeText(name),
                10,
                TextAnchor.MiddleLeft,
                config.TextColor,
                "0.050 0",
                "0.275 1",
                "Name");

            AddText(c, row,
                FormatStatNumber(wipe ? GetWipePoints(d) : GetStatPoints(d)),
                9,
                TextAnchor.MiddleCenter,
                config.TextColor,
                "0.275 0", "0.405 1", "Points");

            AddText(c, row,
                FormatStatNumber(wipe ? d.WipeKills : d.Kills),
                9,
                TextAnchor.MiddleCenter,
                config.TextColor,
                "0.405 0", "0.515 1", "Kills");

            AddText(c, row,
                FormatStatNumber(wipe ? d.WipeDeaths : d.Deaths),
                9,
                TextAnchor.MiddleCenter,
                config.TextColor,
