        private void OpenStatisticsProfile(BasePlayer viewer, ulong targetId)
        {
            if (viewer == null || !viewer.IsConnected) return;
            PlayerData data;
            if (!players.TryGetValue(targetId, out data)) data = new PlayerData();
            BasePlayer target = BasePlayer.FindByID(targetId);
            string name = target != null && !string.IsNullOrEmpty(target.displayName) ? target.displayName : targetId.ToString();

            OpenMenu(viewer, 0);
            CuiHelper.DestroyUi(viewer, MainLayer + ".Content");
            var c = new CuiElementContainer();
            string layer = MainLayer + ".Content.StatisticsProfile";
            AddStatisticsShell(c, layer, "profile");

            AddText(c, layer, "ПРОФИЛЬ ИГРОКА", 16, TextAnchor.MiddleLeft, config.TextColor, "0.025 0.89", "0.55 0.94", "ProfileTitle");
            DrawSteamAvatar(c, layer, targetId, "0.035 0.58", "0.22 0.84", layer + ".Avatar");
            AddText(c, layer, EscapeText(name), 15, TextAnchor.MiddleLeft, config.TextColor, "0.25 0.75", "0.70 0.84", "ProfileName");
            AddText(c, layer, targetId.ToString(), 9, TextAnchor.MiddleLeft, config.SecondaryTextColor, "0.25 0.69", "0.70 0.75", "ProfileId");

            AddStatCard(c, layer, "ОЧКИ", FormatStatNumber(GetStatPoints(data)), "0.25 0.48", "0.39 0.67", "p1");
            AddStatCard(c, layer, "УБИЙСТВА", FormatStatNumber(data.Kills), "0.40 0.48", "0.54 0.67", "p2");
            AddStatCard(c, layer, "СМЕРТИ", FormatStatNumber(data.Deaths), "0.55 0.48", "0.69 0.67", "p3");
            AddStatCard(c, layer, "К/Д", FormatKD(data.Kills, data.Deaths), "0.70 0.48", "0.84 0.67", "p4");
            AddStatCard(c, layer, "НАГРАДА", FormatStatNumber(GetRewardPoints(targetId)), "0.85 0.48", "0.985 0.67", "p5");

            AddResourcePanel(c, layer, "СТАТИСТИКА ФАРМА", new[] { FormatStatNumber(data.OreGathered), FormatStatNumber(data.TotalGathered), FormatPlayTime(data.ActiveSeconds), FormatStatNumber(data.FarmEvents), "0", "0" }, "0.25 0.10", "0.985 0.43", "ProfileFarm");
            c.Add(new CuiButton
            {
                Button = { Command = "infomenu.stats all 0", Color = "0.25 0.27 0.29 1", HighlightedColor = ParseColor(config.ButtonHoverColor) },
                Text = { Text = "НАЗАД", Font = config.Font, FontSize = 10, Align = TextAnchor.MiddleCenter, Color = "0.9 0.9 0.9 1" },
                RectTransform = { AnchorMin = "0.025 0.035", AnchorMax = "0.18 0.095" }
            }, layer);
            CuiHelper.AddUi(viewer, c);
            RequestSteamAvatar(target);
        }

        private string GetPlayerRankText(BasePlayer player, bool wipe)
        {
            if (player == null) return "—";
            List<ulong> ids = players.Keys.ToList();
            PlayerData d;
            if (!players.TryGetValue(player.userID, out d)) return "—";
            double score = wipe ? GetWipePoints(d) : GetStatPoints(d);
            int rank = ids.OrderByDescending(id =>
            {
                PlayerData x; return players.TryGetValue(id, out x) ? (wipe ? GetWipePoints(x) : GetStatPoints(x)) : 0d;
            }).ToList().IndexOf(player.userID) + 1;
            return rank > 0 ? rank.ToString(CultureInfo.InvariantCulture) : "—";
        }

        private double GetStatPoints(PlayerData d)
        {
            if (d == null) return 0d;
            return Math.Max(0d, d.Kills * 25d + d.TotalGathered / 100d + d.ActiveSeconds / 60d);
        }

        private double GetWipePoints(PlayerData d)
        {
            if (d == null) return 0d;
            return Math.Max(0d, d.WipeKills * 25d + d.WipeGathered / 100d + d.WipeActiveSeconds / 60d);
        }

        private string FormatKD(double kills, double deaths)
        {
            if (deaths <= 0) return kills > 0 ? kills.ToString(CultureInfo.InvariantCulture) : "0.00";
            return ((double)kills / deaths).ToString("0.00", CultureInfo.InvariantCulture);
        }

        private int GetRewardPoints(ulong userId)
        {
            try
            {
                if (ServerRewards == null) ServerRewards = plugins.Find("ServerRewards");
                if (ServerRewards == null) return 0;
                object result = ServerRewards.Call("CheckPoints", userId);
                int value;
                if (result != null && int.TryParse(result.ToString(), out value)) return value;
            }
            catch { }
            return 0;
        }

        private void DrawSteamAvatar(CuiElementContainer c, string parent, ulong steamId, string min, string max, string panelName)
        {
            // Для профилей из ТОП используем настоящий Steam-аватар по SteamID.
            // Игрок может быть офлайн — SteamID достаточно, BasePlayer не нужен.
            if (steamId == 0UL)
            {
