        private readonly HashSet<ulong> avatarRequests = new HashSet<ulong>();
        private string GetAvatarKey(ulong id) { return "metalicrust.avatar." + id.ToString(); }

        private void RequestSteamAvatar(BasePlayer player)
        {
            if (player == null || ImageLibrary == null) return;
            ulong id = player.userID;
            string key = GetAvatarKey(id);
            if (!string.IsNullOrEmpty(GetImage(key)) || avatarRequests.Contains(id)) return;
            avatarRequests.Add(id);
            string url = "https://steamcommunity.com/profiles/" + id.ToString() + "/?xml=1";
            webrequest.EnqueueGet(url, (code, response) =>
            {
                avatarRequests.Remove(id);
                if (code != 200 || string.IsNullOrEmpty(response)) return;
                Match m = Regex.Match(response, @"<avatarFull><!\[CDATA\[(.*?)\]\]></avatarFull>", RegexOptions.IgnoreCase | RegexOptions.Singleline);
                if (!m.Success) m = Regex.Match(response, @"<avatarFull>(.*?)</avatarFull>", RegexOptions.IgnoreCase | RegexOptions.Singleline);
                if (!m.Success) return;
                string avatarUrl = System.Net.WebUtility.HtmlDecode(m.Groups[1].Value).Trim();
                if (string.IsNullOrEmpty(avatarUrl)) return;
                ImageLibrary.Call("AddImage", avatarUrl, key);
                // Картинка будет доступна при следующем открытии статистики.
                // Не перерисовываем чужой профиль/текущую вкладку автоматически.
            }, this);
        }

