        private string FormatStatNumber(double value)
        {
            if (value < 1000d) return value.ToString("0", CultureInfo.InvariantCulture);
            if (value < 1000000d) return (value / 1000d).ToString("0.0", CultureInfo.InvariantCulture) + "K";
            return (value / 1000000d).ToString("0.0", CultureInfo.InvariantCulture) + "M";
        }

        private double GetPlayerStatDouble(BasePlayer player, params string[] names)
        {
            if (player == null || names == null)
                return 0d;

            try
            {
                Type type = player.GetType();
                foreach (string name in names)
                {
                    FieldInfo field = type.GetField(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.IgnoreCase);
                    if (field != null)
                    {
                        double number;
                        if (TryConvertStat(field.GetValue(player), out number))
                            return number;
                    }

                    PropertyInfo property = type.GetProperty(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.IgnoreCase);
                    if (property != null)
                    {
                        double number;
                        if (TryConvertStat(property.GetValue(player, null), out number))
                            return number;
                    }
                }
            }
            catch { }

            return 0d;
        }

        private string GetStatRankValue(BasePlayer player, RankProgress progress)
        {
            if (player == null || progress == null)
                return "0";

            PlayerData current;
            if (!players.TryGetValue(player.userID, out current))
                return "0";

            int rank = players.Keys
                .OrderByDescending(id =>
                {
                    PlayerData d;
                    return players.TryGetValue(id, out d) && d != null ? d.ActiveSeconds : 0d;
                })
                .ThenBy(id => id)
                .ToList()
                .IndexOf(player.userID) + 1;

            return rank > 0 ? rank.ToString(CultureInfo.InvariantCulture) : "0";
        }

