        private void AddStatIcon(CuiElementContainer c, string parent, string key, string min, string max, string color)
        {
            if (string.IsNullOrEmpty(key))
                return;

            string png = null;

            try
            {
                if (ImageLibrary != null)
                {
                    string imageName = key != null && key.StartsWith("item_", StringComparison.OrdinalIgnoreCase)
                        ? "MetalicRustStats_Item_" + key
                        : "MetalicRustStats_1to1_" + key;
                    png = ImageLibrary.Call("GetImage", imageName, 0UL, false) as string;
                }
            }
            catch { }

            // Если ImageLibrary ещё не вернула ID — используем те же PNG из файла.
            // Это только резерв: при загрузке плагина они уже добавляются в ImageLibrary.
            if (string.IsNullOrEmpty(png))
                statIcons.TryGetValue(key, out png);

            if (string.IsNullOrEmpty(png))
                return;

            c.Add(new CuiElement
            {
                Parent = parent,
                Components =
                {
                    new CuiRawImageComponent { Png = png, Color = ParseColor(color) },
                    new CuiRectTransformComponent { AnchorMin = min, AnchorMax = max }
                }
            });
        }




