        private void DestroyMenu(BasePlayer player)
        {
            if (player == null)
                return;

            CuiHelper.DestroyUi(player, MainLayer);
            CuiHelper.DestroyUi(player, "UI_KIT_OVERLAY");
            openKitPages.Remove(player.userID);
            openMenuPlayers.Remove(player.userID);
        }

        private void OpenMenu(BasePlayer player, int topIndex, bool showTopTabs = true)
        {
            if (player == null || !player.IsConnected)
                return;

            if (config.TopTabs == null || config.TopTabs.Count == 0)
                return;

            topIndex = Mathf.Clamp(topIndex, 0, config.TopTabs.Count - 1);

            DestroyMenu(player);
            openMenuPlayers.Add(player.userID);

            var container = new CuiElementContainer();

            // Затемнение игрового мира.
            container.Add(new CuiPanel
            {
                CursorEnabled = true,
                Image = { Color = "0 0 0 0.60", FadeIn = 0.18f },
                RectTransform =
                {
                    AnchorMin = "0 0",
                    AnchorMax = "1 1"
                }
            }, "Overlay", MainLayer);

            // Необязательный фон.
            if (config.ShowBackground && ImageLibrary != null && !string.IsNullOrEmpty(config.BackgroundImage))
            {
