        [ConsoleCommand("infomenu.chat.rank")]
        private void ConsoleChatRank(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null) return;

            // Ранги выдаются автоматически по активности. Ручной выбор отключён.
