        [ConsoleCommand("infomenu.chat.namecolor")]
        private void ConsoleChatNameColor(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null) return;
            string hex = arg.GetString(0, "");
            if (string.IsNullOrEmpty(hex)) return;
            if (ColouredChat == null)
            {
                player.ChatMessage("<color=#55ff22>Цвет ника:</color> требуется плагин Coloured Chat.");
                return;
            }
            PlayerData data = GetPlayerData(player);
            if (data != null) data.NameColorHex = hex;
            SaveData();
            player.SendConsoleCommand("chat.say", "/colour " + hex);
            player.ChatMessage("<color=#55ff22>Цвет ника изменён.</color>");
            OpenChatPage(player, 1);
        }

        [ConsoleCommand("infomenu.chat.messagecolor")]
        private void ConsoleChatMessageColor(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null) return;
            string hex = arg.GetString(0, "");
            if (string.IsNullOrEmpty(hex)) return;
            if (ColouredChat == null)
            {
                player.ChatMessage("<color=#55ff22>Цвет сообщения:</color> требуется плагин Coloured Chat.");
                return;
            }
            PlayerData data = GetPlayerData(player);
            if (data != null) data.MessageColorHex = hex;
            SaveData();
            player.SendConsoleCommand("chat.say", "/mcolour " + hex);
            player.ChatMessage("<color=#55ff22>Цвет сообщений изменён.</color>");
            OpenChatPage(player, 1);
        }

        [ConsoleCommand("infomenu.chat.function")]
        private void ConsoleChatFunction(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null) return;
            string key = arg.GetString(0, "");
            PlayerData data = GetPlayerData(player);

            if (string.Equals(key, "pm", StringComparison.OrdinalIgnoreCase))
            {
                data.PrivateMessagesEnabled = !data.PrivateMessagesEnabled;
                SaveData();
                player.ChatMessage("<color=#55ff22>Личные сообщения: " + (data.PrivateMessagesEnabled ? "ВКЛ" : "ВЫКЛ") + "</color>");
                OpenChatPage(player, 1);
                return;
            }

            if (string.Equals(key, "sound", StringComparison.OrdinalIgnoreCase))
            {
                data.ChatSoundEnabled = !data.ChatSoundEnabled;
                SaveData();
                player.ChatMessage("<color=#55ff22>Звуковые эффекты: " + (data.ChatSoundEnabled ? "ВКЛ" : "ВЫКЛ") + "</color>");
                OpenChatPage(player, 1);
            }
        }

        private PlayerData GetPlayerData(BasePlayer player)
        {
            if (player == null) return null;
            PlayerData data;
            if (!players.TryGetValue(player.userID, out data) || data == null)
            {
                data = new PlayerData { FirstSeen = false };
                players[player.userID] = data;
                SaveData();
            }
            return data;
        }

        private string GetCovalencePlayerId(object player)
        {
            if (player == null) return null;
            try
            {
                var prop = player.GetType().GetProperty("Id", BindingFlags.Public | BindingFlags.Instance);
                return prop != null ? prop.GetValue(player, null) as string : null;
            }
            catch { return null; }
        }

        private object OnPMProcessed(object sender, object target, string message)
        {
            if (target == null) return null;
            ulong targetId;
            string targetIdString = GetCovalencePlayerId(target);
            if (!ulong.TryParse(targetIdString, out targetId)) return null;
            PlayerData data;
            if (!players.TryGetValue(targetId, out data) || data == null || data.PrivateMessagesEnabled)
                return null;
            return "<color=#ff4444>Игрок отключил личные сообщения.</color>";
        }

        private void OnBetterChat(Dictionary<string, object> data)
        {
            // Настройка звуков хранится отдельно для каждого игрока.
            // Само воспроизведение оставлено за совместимым sound-плагином, чтобы не менять звук Better Chat.
        }

        private void SetChatGroup(BasePlayer player, string group, List<ChatOption> options, string kind)
        {
            ChatOption selected = options.FirstOrDefault(x => x != null &&
                string.Equals(x.Group ?? "", group ?? "", StringComparison.OrdinalIgnoreCase));
            if (selected == null) return;

            if (!string.IsNullOrEmpty(selected.Permission) && !permission.UserHasPermission(player.UserIDString, selected.Permission))
            {
                player.ChatMessage("<color=#ff4444>У вас нет доступа к этому варианту.</color>");
                return;
            }

            if (BetterChat == null)
            {
                player.ChatMessage("<color=#ff4444>Better Chat не найден.</color>");
                return;
            }

            foreach (ChatOption option in options)
            {
                if (option == null || string.IsNullOrEmpty(option.Group)) continue;
                Server.Command("chat", "user", "remove", player.UserIDString, option.Group);
            }

            if (!string.IsNullOrEmpty(selected.Group))
                Server.Command("chat", "user", "add", player.UserIDString, selected.Group);

            player.ChatMessage("<color=#55ff22>" + kind + " установлен: " + selected.Title + "</color>");
            OpenChatPage(player, 0);
        }

        private object GetBetterChatPlayerObject(BasePlayer player)
        {
            if (player == null)
                return null;

            try
            {
                PropertyInfo property = typeof(BasePlayer).GetProperty(
                    "IPlayer",
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);

                if (property != null)
                    return property.GetValue(player, null);
            }
            catch
            {
            }

            return null;
        }

        private string GetBetterChatPrimaryGroup(BasePlayer player)
        {
            if (BetterChat == null || player == null)
                return "default";

            object iPlayer = GetBetterChatPlayerObject(player);
            if (iPlayer == null)
                return "default";

            try
            {
                object result = BetterChat.Call("API_GetUserGroups", iPlayer);
                var groups = result as System.Collections.IEnumerable;
                if (groups == null) return "default";

                string best = "default";
                int bestPriority = int.MaxValue;
                foreach (object item in groups)
                {
                    JObject obj = item as JObject;
                    if (obj == null) continue;
                    string name = obj["GroupName"] == null ? null : obj["GroupName"].ToString();
                    int priority = 999999;
                    if (obj["Priority"] != null)
                    {
                        try { priority = obj["Priority"].Value<int>(); } catch { }
                    }
                    if (!string.IsNullOrEmpty(name) && priority < bestPriority)
                    {
                        best = name;
                        bestPriority = priority;
                    }
                }
                return best;
            }
            catch { return "default"; }
        }

        private bool HasChatGroup(BasePlayer player, string group)
        {
            if (string.IsNullOrEmpty(group) || BetterChat == null || player == null)
                return false;

            object iPlayer = GetBetterChatPlayerObject(player);
            if (iPlayer == null)
                return false;

            try
            {
                object result = BetterChat.Call("API_GetUserGroups", iPlayer);
                var groups = result as System.Collections.IEnumerable;
                if (groups == null) return false;
                foreach (object item in groups)
                {
                    JObject obj = item as JObject;
                    if (obj == null) continue;
                    string groupName = obj["GroupName"] == null ? string.Empty : obj["GroupName"].ToString();
                    if (string.Equals(groupName, group, StringComparison.OrdinalIgnoreCase))
                        return true;
                }
            }
            catch { }
            return false;
        }

        private string GetPlayerChatPreview(BasePlayer player)
        {
            if (BetterChat == null || player == null)
                return "<color=#55aaff>ST</color>: Всем привет!";

            object iPlayer = GetBetterChatPlayerObject(player);
            if (iPlayer == null)
                return "<color=#55aaff>ST</color>: Всем привет!";

            try
            {
                object result = BetterChat.Call("API_GetFormattedMessage", iPlayer, "Всем привет!", false);
                if (result != null && !string.IsNullOrEmpty(result.ToString()))
                    return result.ToString();
            }
            catch { }
            return "<color=#55aaff>ST</color>: Всем привет!";
        }

        private void OpenChatPage(BasePlayer player, int page)
        {
            if (player == null || !player.IsConnected) return;
            page = Mathf.Clamp(page, 0, 1);
            ClearPageContent(player);

            var c = new CuiElementContainer();
            string content = MainLayer + ".ChatContent";
            c.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0", FadeIn = 0.22f },
                RectTransform = { AnchorMin = "0.195 0.045", AnchorMax = "0.985 0.895" }
            }, MainLayer + ".Main", content);

            // Верхний блок предпросмотра — как на исходном скриншоте.
            c.Add(new CuiPanel
            {
                Image = { Color = ParseColor(config.TopBarColor), FadeIn = 0.16f },
                RectTransform = { AnchorMin = "0.03 0.755", AnchorMax = "0.97 0.97" }
            }, content, content + ".Preview");
            AddText(c, content + ".Preview", "ПРИМЕР ОТОБРАЖЕНИЯ:", 11, TextAnchor.UpperLeft,
                config.SecondaryTextColor, "0.02 0.70", "0.98 0.96", "PreviewTitle");
            AddText(c, content + ".Preview", GetPlayerChatPreview(player), 14, TextAnchor.MiddleLeft,
                config.TextColor, "0.02 0.20", "0.98 0.70", "PreviewText");

            string[] tabs = { "ПРЕФИКСЫ И РАНГИ", "ЦВЕТА И ФУНКЦИИ" };
            float[] mins = { 0.03f, 0.32f };
            float[] maxs = { 0.31f, 0.55f };
            for (int i = 0; i < 2; i++)
            {
                c.Add(new CuiButton
                {
                    Button = { Command = "infomenu.chat " + i, Color = i == page ? ParseColor(config.GreenColor) : ParseColor(config.ButtonColor), HighlightedColor = ParseColor(config.ButtonHoverColor) },
                    Text = { Text = tabs[i], Font = config.Font, FontSize = 11, Align = TextAnchor.MiddleCenter, Color = i == page ? "0 0 0 1" : ParseColor(config.TextColor), FadeIn = 0.12f },
                    RectTransform = { AnchorMin = $"{mins[i]:0.###} 0.69", AnchorMax = $"{maxs[i]:0.###} 0.755" }
                }, content);
            }

            if (page == 0) DrawChatRanks(c, content, player);
            else DrawChatColors(c, content, player);
            CuiHelper.AddUi(player, c);
        }

        private string GetPurchasedTier(BasePlayer player)
        {
            if (player == null)
                return string.Empty;

            // Сначала учитываем новые сроки покупок. Приоритет: ELITE > PREMIUM > VIP.
            long now = CurrentUnix();
            if (GetTierExpiry(player, "elite") > now) return "ELITE";
            if (GetTierExpiry(player, "premium") > now) return "PREMIUM";
            if (GetTierExpiry(player, "vip") > now) return "VIP";

            // Группа BetterChat/oxide сама по себе НЕ считается покупкой.
            // VIP/PREMIUM/ELITE активируются только после покупки в магазине.
            return string.Empty;
        }

        private long GetTierExpiry(BasePlayer player, string tier)
        {
            if (player == null || string.IsNullOrEmpty(tier))
                return 0;

            PlayerData data = GetPlayerData(player);
            if (data == null)
                return 0;

            switch (tier.ToLowerInvariant())
            {
                case "vip": return data.VipExpiresAt;
                case "premium": return data.PremiumExpiresAt;
                case "elite": return data.EliteExpiresAt;
            }
            return 0;
        }

        private void SetTierExpiry(BasePlayer player, string tier, long value)
        {
            PlayerData data = GetPlayerData(player);
            if (data == null) return;

            switch (tier.ToLowerInvariant())
            {
                case "vip": data.VipExpiresAt = value; break;
                case "premium": data.PremiumExpiresAt = value; break;
                case "elite": data.EliteExpiresAt = value; break;
            }
            SaveData();
        }

        private void AddTierDays(BasePlayer player, string tier, int days)
        {
            if (player == null || string.IsNullOrEmpty(tier) || days <= 0)
                return;

            long now = CurrentUnix();
            long current = GetTierExpiry(player, tier);
            long baseTime = current > now ? current : now;
            SetTierExpiry(player, tier, baseTime + days * 86400L);
        }

        private int GetPlayerTierLevel(BasePlayer player)
        {
            if (player == null)
                return 0;

            string tier = GetPurchasedTier(player);
            if (string.Equals(tier, "ELITE", StringComparison.OrdinalIgnoreCase)) return 3;
            if (string.Equals(tier, "PREMIUM", StringComparison.OrdinalIgnoreCase)) return 2;
            if (string.Equals(tier, "VIP", StringComparison.OrdinalIgnoreCase)) return 1;
            return 0;
        }

        private int GetColorRequiredTier(int index)
        {
            if (index <= 0) return 0;
            if (index == 1) return 1;
            if (index == 2) return 2;
            return 3;
        }

        private bool HasPurchasedStatus(BasePlayer player, string status)
        {
            if (player == null || string.IsNullOrEmpty(status))
                return false;

            if (HasChatGroup(player, status))
                return true;

            try
            {
                if (permission.UserHasGroup(player.UserIDString, status))
                    return true;
            }
            catch { }

            try
            {
                if (permission.UserHasPermission(player.UserIDString, status))
                    return true;
            }
            catch { }

            try
            {
                if (permission.UserHasPermission(player.UserIDString, "metalicrust." + status))
                    return true;
            }
            catch { }

            return false;
        }

        private void ExpirePurchasedTiers(BasePlayer player)
        {
            if (player == null) return;

            long now = CurrentUnix();
            PlayerData data = GetPlayerData(player);
            if (data == null) return;

            bool changed = false;
            if (data.VipExpiresAt > 0 && data.VipExpiresAt <= now) { data.VipExpiresAt = 0; Server.Command("oxide.usergroup remove " + player.UserIDString + " vip"); changed = true; }
            if (data.PremiumExpiresAt > 0 && data.PremiumExpiresAt <= now) { data.PremiumExpiresAt = 0; Server.Command("oxide.usergroup remove " + player.UserIDString + " premium"); changed = true; }
            if (data.EliteExpiresAt > 0 && data.EliteExpiresAt <= now) { data.EliteExpiresAt = 0; Server.Command("oxide.usergroup remove " + player.UserIDString + " elite"); changed = true; }
            if (changed) SaveData();
        }

        private void SetPurchasedChatGroup(BasePlayer player, string tier)
        {
            if (player == null || string.IsNullOrEmpty(tier))
                return;

            string targetGroup = tier.ToLowerInvariant();
            try
            {
                if (!string.Equals(targetGroup, "vip", StringComparison.OrdinalIgnoreCase))
                    Server.Command("chat", "user", "remove", player.UserIDString, "vip");
                if (!string.Equals(targetGroup, "premium", StringComparison.OrdinalIgnoreCase))
                    Server.Command("chat", "user", "remove", player.UserIDString, "premium");
                if (!string.Equals(targetGroup, "elite", StringComparison.OrdinalIgnoreCase))
                    Server.Command("chat", "user", "remove", player.UserIDString, "elite");

                Server.Command("chat", "user", "add", player.UserIDString, targetGroup);
            }
            catch (Exception ex)
            {
                PrintWarning("[InfoMenu] Не удалось установить группу после покупки " + tier + ": " + ex.Message);
            }
        }

        private void SyncPurchasedStatus(BasePlayer player, bool notify)
        {
            if (player == null || !player.IsConnected)
                return;

            ExpirePurchasedTiers(player);
            string tier = GetPurchasedTier(player);
            if (string.IsNullOrEmpty(tier))
            {
                if (notify)
                {
                    player.ChatMessage("<color=#ff4444>Купленный VIP/PREMIUM/ELITE не найден.</color>");
                    OpenChatPage(player, 0);
                }
                return;
            }


            PlayerData data = GetPlayerData(player);
            string rank = GetPurchasedRank(player);
            bool changed = data != null && !string.Equals(data.AutoRank, rank, StringComparison.OrdinalIgnoreCase);
            if (data != null)
                data.AutoRank = rank;
            if (changed)
                SaveData();

            if (notify)
            {
                player.ChatMessage("<color=#55ff22>Статус: " + tier + " | Ранг: " + rank + "</color>");
                OpenChatPage(player, 0);
            }
        }

        private string GetPurchasedPrefix(BasePlayer player)
        {
            return GetPurchasedTier(player);
        }

        private string GetPurchasedRank(BasePlayer player)
        {
            switch (GetPurchasedTier(player))
            {
                case "ELITE": return "ЗАДРОТ";
                case "PREMIUM": return "ФАРМИЛА";
                case "VIP": return "МЕСТНЫЙ";
                default: return "КЕПКА";
            }
        }

