        private void DrawConditionBar(CuiElementContainer c, string parent, string title, double value, string min, string max, string name)
        {
            double percent = Math.Max(0d, Math.Min(100d, value));
            string fill = (percent / 100d).ToString("0.###", CultureInfo.InvariantCulture);
            string[] a = min.Split(' ');
            string[] b = max.Split(' ');
            float minY = float.Parse(a[1], CultureInfo.InvariantCulture);
            float maxY = float.Parse(b[1], CultureInfo.InvariantCulture);
            string barMin = a[0] + " " + (minY - 0.055f).ToString("0.###", CultureInfo.InvariantCulture);
            string barMax = b[0] + " " + (maxY - 0.055f).ToString("0.###", CultureInfo.InvariantCulture);
            string barName = parent + "." + name + ".Bar";

            AddText(c, parent, title + ": " + percent.ToString("0.00", CultureInfo.InvariantCulture) + " %", 10, TextAnchor.MiddleLeft, config.TextColor, min, max, name + ".Text");
            c.Add(new CuiPanel
            {
                Image = { Color = "0.04 0.05 0.05 1" },
                RectTransform = { AnchorMin = barMin, AnchorMax = barMax }
            }, parent, barName);
            c.Add(new CuiPanel
            {
                Image = { Color = ParseColor(config.GreenColor) },
                RectTransform = { AnchorMin = "0 0", AnchorMax = fill + " 1" }
            }, barName, barName + ".Fill");
        }

        private void DrawPurchasedColumn(CuiElementContainer c, string content, string[] values, string selectedValue, float left, float right)
        {
            float y = 0.565f;
            foreach (string value in values)
            {
                bool selected = string.Equals(value, selectedValue, StringComparison.OrdinalIgnoreCase);
                c.Add(new CuiButton
                {
                    Button = { Command = "", Color = ParseColor(selected ? config.GreenColor : config.ButtonColor), HighlightedColor = ParseColor(selected ? config.GreenColor : config.ButtonHoverColor) },
                    Text = { Text = selected ? "✓ " + value : value, Font = config.Font, FontSize = 10, Align = TextAnchor.MiddleCenter, Color = selected ? "0 0 0 1" : ParseColor(config.TextColor), FadeIn = 0.12f },
                    RectTransform = { AnchorMin = $"{left:0.###} {y:0.###}", AnchorMax = $"{right:0.###} {(y + 0.052f):0.###}" }
                }, content);
                y -= 0.058f;
            }
        }

        // -------------------------
        // TRACKING СТАТИСТИКИ
        // -------------------------
        private readonly Dictionary<uint, ulong> lastEntityAttackers = new Dictionary<uint, ulong>();
        private readonly HashSet<uint> trackedExplosiveEntities = new HashSet<uint>();

        private void EnsureStatDictionaries(PlayerData data)
        {
            if (data == null) return;
            if (data.TrackedResources == null) data.TrackedResources = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
            if (data.TrackedExplosives == null) data.TrackedExplosives = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
        }
        private void AddTracked(Dictionary<string, double> dict, string key, double amount)
        {
            if (dict == null || string.IsNullOrEmpty(key) || amount <= 0d) return;
            double old; dict.TryGetValue(key, out old); dict[key] = old + amount;
        }
        private string TrackedValue(PlayerData data, string key, bool explosive = false)
        {
            if (data == null) return "0";
            EnsureStatDictionaries(data);
            double value; var dict = explosive ? data.TrackedExplosives : data.TrackedResources;
            return dict.TryGetValue(key, out value) ? FormatStatNumber(value) : "0";
        }
        private BasePlayer GetStatAttacker(HitInfo info)
        {
            if (info == null) return null;
            BasePlayer p = info.InitiatorPlayer;
            if (p != null) return p;
            BaseEntity e = info.Initiator;
            return e != null ? e.ToPlayer() : null;
        }
        private string StatEntityName(BaseEntity entity)
        {
            if (entity == null) return string.Empty;
            return ((entity.ShortPrefabName ?? "") + " " + (entity.PrefabName ?? "") + " " + entity.GetType().Name).ToLowerInvariant();
        }
        private bool IsStatTank(BaseEntity e) { string n = StatEntityName(e); return n.Contains("bradley") || n.Contains("tank"); }
        private bool IsStatHelicopter(BaseEntity e) { string n = StatEntityName(e); return n.Contains("patrolhelicopter") || n.Contains("patrol_helicopter") || n.Contains("attackhelicopter") || n.Contains("attack_helicopter"); }
        private bool IsStatBarrel(BaseEntity e) { string n = StatEntityName(e); return n.Contains("barrel") && !n.Contains("wheel"); }
        private bool IsStatAnimal(BaseEntity e)
        {
            string n = StatEntityName(e);
            string[] a = { "bear", "wolf", "boar", "stag", "chicken", "horse", "shark", "polarbear", "polar_bear", "deer", "fish", "tiger", "crocodile" };
            for (int i = 0; i < a.Length; i++) if (n.Contains(a[i])) return true;
            return false;
        }
        private bool IsStatCrate(BaseEntity e)
        {
            string n = StatEntityName(e);
            return n.Contains("crate") || n.Contains("loot_barrel_1") || n.Contains("loot_barrel_2");
        }
        private bool IsStatCobaltVault(BaseEntity e)
        {
            string n = StatEntityName(e);
            return (n.Contains("cobalt") && (n.Contains("vault") || n.Contains("valut") || n.Contains("lab"))) || n.Contains("cobaltvault") || n.Contains("cobalt_vault");
        }
        private bool IsStatNpc(BaseEntity e)
        {
            if (e == null) return false;
            if (IsStatAnimal(e) || IsStatTank(e) || IsStatHelicopter(e)) return false;
            string n = StatEntityName(e), t = e.GetType().Name.ToLowerInvariant();
            if (e is BasePlayer bp && bp.IsConnected) return false;
            return t.Contains("scientist") || t.Contains("npc") || t.Contains("humanai") || n.Contains("scientist") || n.Contains("scientistnpc") || n.Contains("human_npc") || n.Contains("npcplayer") || n.Contains("npc");
        }
        private void RememberLastAttacker(BaseCombatEntity entity, HitInfo info)
        {
            BasePlayer p = GetStatAttacker(info);
            if (entity == null || p == null || !p.IsConnected || entity.net == null) return;
            lastEntityAttackers[(uint)entity.net.ID.Value] = p.userID;
        }
        private BasePlayer GetRememberedAttacker(BaseCombatEntity entity, HitInfo info)
        {
            BasePlayer p = GetStatAttacker(info);
            if (p != null) return p;
            if (entity == null || entity.net == null) return null;
            ulong uid;
            return lastEntityAttackers.TryGetValue((uint)entity.net.ID.Value, out uid) ? BasePlayer.FindByID(uid) : null;
        }
        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            if (entity == null || info == null) return null;
            BasePlayer attacker = GetStatAttacker(info);
            if (attacker == null || !attacker.IsConnected) return null;
            RememberLastAttacker(entity, info);
            if (entity is BuildingBlock)
            {
                float damage = info.damageTypes != null ? info.damageTypes.Total() : 0f;
                if (damage > 0f)
                {
                    PlayerData d = GetPlayerData(attacker);
                    if (d != null) d.BlockDamage += damage;
                }
            }
            return null;
        }
        private object OnEntityDeath(BaseCombatEntity entity, HitInfo info)
        {
            if (entity == null) return null;
            BasePlayer attacker = GetRememberedAttacker(entity, info);
            PlayerData ad = attacker != null ? GetPlayerData(attacker) : null;
            if (ad != null)
            {
                BasePlayer bp = entity as BasePlayer;
                if (bp != null)
                {
                    if (bp.IsConnected && bp.userID != attacker.userID) { ad.Kills += 1d; ad.WipeKills += 1d; }
                    else if (!bp.IsConnected && IsStatNpc(bp)) ad.NpcKills += 1d;
                }
                else if (IsStatAnimal(entity)) ad.AnimalsKilled += 1d;
                if (IsStatTank(entity)) ad.TanksDestroyed += 1d;
                else if (IsStatHelicopter(entity)) ad.HelicoptersDestroyed += 1d;
                else if (IsStatBarrel(entity)) ad.BarrelsDestroyed += 1d;
                SaveData();
            }
            BasePlayer victim = entity as BasePlayer;
            if (victim != null && victim.IsConnected)
            {
                PlayerData vd = GetPlayerData(victim);
                if (vd != null) { vd.Deaths += 1d; vd.WipeDeaths += 1d; SaveData(); }
            }
            if (entity.net != null) lastEntityAttackers.Remove((uint)entity.net.ID.Value);
            return null;
        }
        private void OnLootEntity(BasePlayer player, BaseEntity entity)
        {
            if (player == null || !player.IsConnected || entity == null) return;
            PlayerData d = GetPlayerData(player);
            if (d == null) return;
            if (IsStatCobaltVault(entity)) d.CobaltVaultsOpened += 1d;
            else if (IsStatCrate(entity)) d.CratesOpened += 1d;
            else return;
            SaveData();
        }
        private void TrackExplosive(BasePlayer player, string shortname, double amount)
        {
            if (player == null || !player.IsConnected || amount <= 0d) return;
            PlayerData d = GetPlayerData(player);
            if (d == null) return;
            EnsureStatDictionaries(d); AddTracked(d.TrackedExplosives, shortname, amount); SaveData();
        }
        private void OnItemUse(Item item, int amount)
        {
            if (item == null || item.info == null) return;
            string s = item.info.shortname ?? "";
            if (s != "ammo.rifle.explosive") return;
            BasePlayer player = item.GetOwnerPlayer();
            if (player != null) TrackExplosive(player, s, Math.Max(1, amount));
        }
        private bool IsTrackedTimedExplosive(BaseEntity entity, out string shortname)
        {
            shortname = string.Empty;
            if (entity == null) return false;

            string n = (StatEntityName(entity) ?? string.Empty).ToLowerInvariant();
            if (n.Contains("explosive.satchel.deployed") || n.Contains("explosive.satchel") || n.Contains("satchel_charge") || n.Contains("satchelcharge"))
            {
                shortname = "explosive.satchel";
                return true;
            }

            if (n.Contains("explosive.timed.deployed") || n.Contains("explosive.timed") || n.Contains("timed_explosive") || n.Contains("timedexplosive"))
            {
                shortname = "explosive.timed";
                return true;
            }

            return false;
        }

        private void TrackExplosiveEntity(BasePlayer player, BaseEntity entity)
        {
            if (player == null || !player.IsConnected || entity == null) return;

            string shortname;
            if (!IsTrackedTimedExplosive(entity, out shortname)) return;

            uint entityId = entity.net != null ? (uint)entity.net.ID.Value : 0u;
            if (entityId != 0u)
            {
                if (trackedExplosiveEntities.Contains(entityId)) return;
                trackedExplosiveEntities.Add(entityId);
            }

            TrackExplosive(player, shortname, 1d);
        }

        // В актуальном Rust этот hook имеет именно 2 аргумента.
