        private void OnEntitySpawned(BaseNetworkable networkable)
        {
            BaseEntity entity = networkable as BaseEntity;
            if (entity == null) return;

            string shortname;
            if (!IsTrackedTimedExplosive(entity, out shortname)) return;

            // Обычно владелец уже записан в OwnerID. Это резервный путь на случай,
            // если OnExplosiveThrown не был вызван другим плагином/версией Rust.
