        private class RankProgress
        {
            public double TimePercent;
            public double FarmPercent;
            public double ActivityPercent;
            public double Overall;
            public string RankGroup;
            public string RankTitle;
            public double OreGathered;
            public double ActiveSeconds;
        }

        private void EnsureRankTracking(BasePlayer player)
        {
            if (player == null) return;
            PlayerData data = GetPlayerData(player);
            if (data == null) return;
            if (data.LastActiveUnix <= 0)
                data.LastActiveUnix = CurrentUnix();

            // Создаём начальный сэмпл активности, чтобы старое накопленное время
            // не превращалось в AFK-время после обновления плагина.
            if (!data.HasActivitySample)
            {
                data.LastActivityX = player.transform.position.x;
                data.LastActivityY = player.transform.position.y;
                data.LastActivityZ = player.transform.position.z;
                data.LastActivityYaw = player.transform.eulerAngles.y;
                data.LastActivityPitch = player.transform.eulerAngles.x;
                data.HasActivitySample = true;
            }

            if (string.IsNullOrEmpty(data.AutoRank))
                data.AutoRank = "cap";
            ApplyAutoRank(player, false);
        }

        private bool HasPlayerActivity(BasePlayer player, PlayerData data)
        {
            if (player == null || data == null)
                return false;

            Vector3 pos = player.transform.position;
            Vector3 euler = player.transform.eulerAngles;

            if (!data.HasActivitySample)
            {
                data.LastActivityX = pos.x;
                data.LastActivityY = pos.y;
                data.LastActivityZ = pos.z;
                data.LastActivityYaw = euler.y;
                data.LastActivityPitch = euler.x;
                data.HasActivitySample = true;
                return false;
            }

            float dx = pos.x - data.LastActivityX;
            float dy = pos.y - data.LastActivityY;
            float dz = pos.z - data.LastActivityZ;
            float distanceSquared = dx * dx + dy * dy + dz * dz;
            float yawDelta = Mathf.Abs(Mathf.DeltaAngle(data.LastActivityYaw, euler.y));
            float pitchDelta = Mathf.Abs(Mathf.DeltaAngle(data.LastActivityPitch, euler.x));

            data.LastActivityX = pos.x;
            data.LastActivityY = pos.y;
            data.LastActivityZ = pos.z;
            data.LastActivityYaw = euler.y;
            data.LastActivityPitch = euler.x;

            // Любое заметное движение или движение камеры = игрок активен.
            // Если персонаж просто стоит/смотрит в одну точку, время не начисляется.
            return distanceSquared >= 0.01f || yawDelta >= 1.0f || pitchDelta >= 1.0f;
        }

        private void UpdateActiveTimeAndRanks()
        {
            long now = CurrentUnix();
            foreach (BasePlayer player in BasePlayer.activePlayerList.ToList())
            {
                if (player == null || !player.IsConnected) continue;
                PlayerData data = GetPlayerData(player);
                if (data == null) continue;

                bool active = HasPlayerActivity(player, data);
                long last = data.LastActiveUnix;
                if (last <= 0 || now <= last || now - last > 300)
                    last = now - 60;

                double delta = Math.Min(120d, Math.Max(0d, now - last));
                if (active)
                {
                    data.ActiveSeconds += delta;
                    data.WipeActiveSeconds += delta;
                }
                data.LastActiveUnix = now;
                ApplyAutoRank(player, false);
            }
            SaveData();
        }

        private readonly Dictionary<ulong, Tuple<long, double>> recentClothInventory = new Dictionary<ulong, Tuple<long, double>>();

        private void OnItemAddedToContainer(ItemContainer container, Item item)
        {
            if (container == null || item == null || item.info == null) return;
            if (!string.Equals(item.info.shortname, "cloth", StringComparison.OrdinalIgnoreCase)) return;

            BasePlayer player = container.playerOwner;
            if (player == null || !player.IsConnected) return;

            PlayerData data = GetPlayerData(player);
            if (data == null) return;

            double amount = Math.Max(0d, item.amount);
            if (amount <= 0d) return;

            EnsureStatDictionaries(data);
            AddTracked(data.TrackedResources, "cloth", amount);
            data.TotalGathered += amount;
            data.WipeGathered += amount;
            data.FarmEvents += 1d;

            long now = CurrentUnix();
            if (data.LastGatherUnix > 0 && now - data.LastGatherUnix <= config.RankProgress.FrequentFarmWindowSeconds)
                data.FrequentFarmEvents += 1d;
            data.LastGatherUnix = now;
            data.LastActiveUnix = now;
            recentClothInventory[player.userID] = Tuple.Create(now, amount);

            ApplyAutoRank(player, false);
            SaveData();
        }

