        private void DrawColorButtons(CuiElementContainer c, string content, List<ChatColorOption> colors, string commandPrefix, float left, float right)
        {
            if (colors == null || colors.Count == 0) return;

            int colorCount = Mathf.Min(colors.Count, 5);

            BasePlayer player = BasePlayer.FindByID(_currentChatPlayerId);
            int tierLevel = GetPlayerTierLevel(player);
            bool nameColor = commandPrefix.IndexOf("namecolor", StringComparison.OrdinalIgnoreCase) >= 0;
            PlayerData playerData = GetPlayerData(player);
            string selectedHex = nameColor ? (playerData == null ? "" : playerData.NameColorHex) : (playerData == null ? "" : playerData.MessageColorHex);

            float gap = 0.012f;
            float width = (right - left - gap * (colorCount - 1)) / colorCount;

            for (int i = 0; i < colorCount; i++)
            {
                string hex = colors[i] != null && !string.IsNullOrEmpty(colors[i].Hex) ? colors[i].Hex : "#FFFFFF";
                int required = GetColorRequiredTier(i);
                bool allowed = tierLevel >= required;
                bool selected = string.Equals(hex, selectedHex, StringComparison.OrdinalIgnoreCase);
                float x = left + i * (width + gap);
                string buttonName = content + ".ColorButton." + (nameColor ? "Name" : "Message") + "." + i;

                c.Add(new CuiButton
                {
                    Button =
                    {
                        Command = allowed ? commandPrefix + hex : "",
                        Color = HexToCui(hex),
                        HighlightedColor = allowed ? "1 1 1 0.85" : HexToCui(hex)
                    },
                    Text =
                    {
                        Text = allowed && selected ? "✓" : "",
                        Font = config.Font,
                        FontSize = 16,
                        Align = TextAnchor.MiddleCenter,
                        Color = allowed && selected ? ParseColor(config.GreenColor) : "1 1 1 1"
                    },
                    RectTransform =
                    {
                        AnchorMin = $"{x:0.###} 0.545",
                        AnchorMax = $"{(x + width):0.###} 0.605"
                    }
                }, content, buttonName);

                // Заблокированный цвет: маленький красный X.
                // Это обычный текст из ASCII и не зависит от emoji/шрифта.
                if (!allowed && config.Chat.ShowLocked)
                {
                    c.Add(new CuiLabel
                    {
                        Text = { Text = "X", Font = config.Font, FontSize = 13, Align = TextAnchor.MiddleCenter, Color = "1 0.12 0.12 1", FadeIn = 0.12f },
                        RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }
                    }, buttonName, buttonName + ".LockedX");
                }
            }
        }

        private string HexToCui(string hex)
        {
            if (string.IsNullOrEmpty(hex)) return "1 1 1 1";
            hex = hex.Trim().TrimStart('#');
            if (hex.Length != 6) return "1 1 1 1";
            try
            {
                float r = int.Parse(hex.Substring(0, 2), NumberStyles.HexNumber) / 255f;
                float g = int.Parse(hex.Substring(2, 2), NumberStyles.HexNumber) / 255f;
                float b = int.Parse(hex.Substring(4, 2), NumberStyles.HexNumber) / 255f;
                return string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###} {2:0.###} 1", r, g, b);
            }
            catch { return "1 1 1 1"; }
        }

