        #region IQKits

        private class IQKitEntry
        {
            public string Category;
            public string CategoryTitle;
            public string Key;
            public string Title;
            public bool CategoryAllowed;
            public bool KitAllowed;

            public IQKitEntry(string category, string categoryTitle, string key, string title, bool categoryAllowed, bool kitAllowed)
            {
                Category = category;
                CategoryTitle = categoryTitle;
                Key = key;
                Title = title;
                CategoryAllowed = categoryAllowed;
                KitAllowed = kitAllowed;
            }

            public bool IsAllowed => CategoryAllowed && KitAllowed;
        }

        private object GetReflectionMember(object instance, string memberName)
        {
            if (instance == null || string.IsNullOrEmpty(memberName))
                return null;

            Type type = instance.GetType();
            const BindingFlags flags = BindingFlags.Instance | BindingFlags.Static |
                                       BindingFlags.Public | BindingFlags.NonPublic |
                                       BindingFlags.FlattenHierarchy;

            while (type != null)
            {
                FieldInfo field = type.GetField(memberName, flags);
                if (field == null)
                    field = type.GetField(memberName, flags | BindingFlags.IgnoreCase);

                if (field != null)
                {
                    try
                    {
                        return field.GetValue(field.IsStatic ? null : instance);
                    }
                    catch { }
                }

                PropertyInfo property = type.GetProperty(memberName, flags);
                if (property == null)
                    property = type.GetProperty(memberName, flags | BindingFlags.IgnoreCase);

                if (property != null && property.GetIndexParameters().Length == 0)
                {
                    try
                    {
                        MethodInfo getter = property.GetGetMethod(true);
                        if (getter != null)
                            return property.GetValue(getter.IsStatic ? null : instance, null);
                    }
                    catch { }
                }

                type = type.BaseType;
            }

            return null;
        }

        private string GetReflectionString(object instance, string memberName, string fallback = "")
        {
            object value = GetReflectionMember(instance, memberName);
            return value == null ? fallback : value.ToString();
        }

        private bool GetReflectionBool(object instance, string memberName, bool fallback = false)
        {
            object value = GetReflectionMember(instance, memberName);
            if (value == null)
                return fallback;

            try { return Convert.ToBoolean(value, CultureInfo.InvariantCulture); }
            catch { return fallback; }
        }

        private bool TryConvertDouble(object value, out double result)
        {
            result = 0.0;
            if (value == null)
                return false;

            try
            {
                result = Convert.ToDouble(value, CultureInfo.InvariantCulture);
                return !double.IsNaN(result) && !double.IsInfinity(result);
            }
            catch { return false; }
        }

        private IEnumerable<KeyValuePair<object, object>> EnumerateDictionary(object value)
        {
            var dictionary = value as System.Collections.IDictionary;
            if (dictionary != null)
            {
                foreach (System.Collections.DictionaryEntry entry in dictionary)
                    yield return new KeyValuePair<object, object>(entry.Key, entry.Value);
                yield break;
            }

            var enumerable = value as System.Collections.IEnumerable;
            if (enumerable == null)
                yield break;

            foreach (object item in enumerable)
            {
                if (item == null)
                    continue;

                object key = GetReflectionMember(item, "Key");
                object val = GetReflectionMember(item, "Value");
                if (key != null)
                    yield return new KeyValuePair<object, object>(key, val);
            }
        }

        private bool HasIQKitPermissions(BasePlayer player, object kitInfo)
        {
            if (player == null || kitInfo == null)
                return false;

            object permissionsObject = GetReflectionMember(kitInfo, "additionalPermissions");
            var permissions = permissionsObject as System.Collections.IEnumerable;
            if (permissions == null)
                return true;

            bool hasPermissionEntries = false;
            foreach (object item in permissions)
            {
                string permissionName = item == null ? string.Empty : item.ToString();
                if (string.IsNullOrWhiteSpace(permissionName))
                    continue;

                hasPermissionEntries = true;
                if (!permission.UserHasPermission(player.UserIDString, permissionName))
                    return false;
            }

            return true;
        }

        private string GetIQKitLanguageText(object languageText, string fallback)
        {
            if (languageText == null)
                return fallback;

            string russian = GetReflectionString(languageText, "russianText");
            if (!string.IsNullOrWhiteSpace(russian))
                return russian;

            string english = GetReflectionString(languageText, "englishText");
            if (!string.IsNullOrWhiteSpace(english))
                return english;

            string text = languageText.ToString();
            return string.IsNullOrWhiteSpace(text) ? fallback : text;
        }

        private List<IQKitEntry> GetIQKits(BasePlayer player)
        {
            var result = new List<IQKitEntry>();
            Plugin iq = GetIQKitsPlugin();

            if (iq == null || player == null)
                return result;

            try
            {
                object iqConfig = GetReflectionMember(iq, "config");
                object categoryObject = GetReflectionMember(iqConfig, "categoryKits");

                if (categoryObject == null)
                {
                    PrintWarning("[InfoMenu] IQKits: не найдено поле categoryKits в конфигурации.");
                    return result;
                }

                bool sortedPermissions = GetReflectionBool(iqConfig, "sortedPermissions", false);
                var privileged = new List<IQKitEntry>();
                var normal = new List<IQKitEntry>();

                foreach (var categoryEntry in EnumerateDictionary(categoryObject))
                {
                    string categoryKey = categoryEntry.Key == null ? string.Empty : categoryEntry.Key.ToString();
                    object categoryInfo = categoryEntry.Value;
                    if (string.IsNullOrWhiteSpace(categoryKey) || categoryInfo == null)
                        continue;

                    bool hideCategoryPermission = GetReflectionBool(categoryInfo, "hideCategoryPermission", false);
                    string categoryPermission = GetReflectionString(categoryInfo, "permission");
                    bool categoryAllowed = string.IsNullOrWhiteSpace(categoryPermission) ||
                                           permission.UserHasPermission(player.UserIDString, categoryPermission);

                    // hideCategoryPermission = true -> категория действительно скрывается без права.
                    // false -> категория и ВСЕ её киты остаются видимыми, даже если конкретный кит закрыт правом.
                    if (hideCategoryPermission && !categoryAllowed)
                        continue;

                    string categoryTitle = GetIQKitLanguageText(
                        GetReflectionMember(categoryInfo, "title"), categoryKey);

                    object kitList = GetReflectionMember(categoryInfo, "kitList");
                    if (kitList == null)
                        continue;

                    foreach (var kitEntry in EnumerateDictionary(kitList))
                    {
                        string kitKey = kitEntry.Key == null ? string.Empty : kitEntry.Key.ToString();
                        object kitInfo = kitEntry.Value;
                        if (string.IsNullOrWhiteSpace(kitKey) || kitInfo == null)
                            continue;

                        bool kitAllowed = HasIQKitPermissions(player, kitInfo);

                        string kitTitle = GetIQKitLanguageText(
                            GetReflectionMember(kitInfo, "title"), kitKey);

                        var entry = new IQKitEntry(
                            categoryKey,
                            categoryTitle,
                            kitKey,
                            kitTitle,
                            categoryAllowed,
                            kitAllowed);

                        bool privilegedCategory = !string.IsNullOrWhiteSpace(categoryPermission) && categoryAllowed;
                        if (sortedPermissions && privilegedCategory)
                            privileged.Add(entry);
                        else
                            normal.Add(entry);
                    }
                }

                if (sortedPermissions)
                    result.AddRange(privileged);
                result.AddRange(normal);

                // КОПТЕР: после покупки w5 должен отображаться в КИТАХ
                // даже если категория/фильтр IQKits скрывает закрытые наборы.
                bool copterAccess = permission.UserHasPermission(player.UserIDString, "iqkits.w5");
                PlayerData copterPlayerData = GetPlayerData(player);
                copterAccess = copterAccess || (copterPlayerData != null && copterPlayerData.PendingCopterKit);

                if (copterAccess && !result.Exists(x => IsCopterKitKey(x.Key)))
                {
                    foreach (var categoryEntry in EnumerateDictionary(categoryObject))
                    {
                        string categoryKey = categoryEntry.Key == null ? string.Empty : categoryEntry.Key.ToString();
                        object categoryInfo = categoryEntry.Value;
                        if (string.IsNullOrWhiteSpace(categoryKey) || categoryInfo == null)
                            continue;

                        object kitList = GetReflectionMember(categoryInfo, "kitList");
                        if (kitList == null)
                            continue;

                        foreach (var kitEntry in EnumerateDictionary(kitList))
                        {
                            string kitKey = kitEntry.Key == null ? string.Empty : kitEntry.Key.ToString();
                            if (!IsCopterKitKey(kitKey))
                                continue;

                            object kitInfo = kitEntry.Value;
                            if (kitInfo == null)
                                break;

                            string categoryTitle = GetIQKitLanguageText(GetReflectionMember(categoryInfo, "title"), categoryKey);
                            string kitTitle = GetIQKitLanguageText(GetReflectionMember(kitInfo, "title"), kitKey);
                            result.Add(new IQKitEntry(categoryKey, categoryTitle, kitKey, kitTitle, true, true));
                            break;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                PrintError("[InfoMenu] Ошибка чтения IQKits 2.6.7: " + ex);
            }

            return result;
        }

        private string GetKitStatusKey(string category, string key)
        {
            return (category ?? string.Empty) + "::" + (key ?? string.Empty);
        }

        private HashSet<string> GetRedeemedSet(ulong userId)
        {
            HashSet<string> set;
            if (!redeemedKitKeys.TryGetValue(userId, out set))
            {
                set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                redeemedKitKeys[userId] = set;
            }
            return set;
        }

        private HashSet<string> GetFailedSet(ulong userId)
        {
            HashSet<string> set;
            if (!failedKitKeys.TryGetValue(userId, out set))
            {
                set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                failedKitKeys[userId] = set;
            }
            return set;
        }

        private double GetKitRemainingCooldown(BasePlayer player, IQKitEntry kit)
        {
            Plugin iq = GetIQKitsPlugin();
            if (iq == null || player == null || kit == null)
                return 0.0;

            try
            {
                object repository = GetReflectionMember(iq, "repositoryKits");
                object playerRepository = null;

                foreach (var entry in EnumerateDictionary(repository))
                {
                    if (entry.Key != null &&
                        string.Equals(entry.Key.ToString(), player.UserIDString, StringComparison.OrdinalIgnoreCase))
                    {
                        playerRepository = entry.Value;
                        break;
                    }
                }

                object categoryRepository = null;
                foreach (var entry in EnumerateDictionary(playerRepository))
                {
                    if (entry.Key != null &&
                        string.Equals(entry.Key.ToString(), kit.Category, StringComparison.OrdinalIgnoreCase))
                    {
                        categoryRepository = entry.Value;
                        break;
                    }
                }

                object playerKitsTaked = GetReflectionMember(categoryRepository, "playerKitsTaked");
                object playerKitInfo = null;
                foreach (var entry in EnumerateDictionary(playerKitsTaked))
                {
                    if (entry.Key != null &&
                        string.Equals(entry.Key.ToString(), kit.Key, StringComparison.OrdinalIgnoreCase))
                    {
                        playerKitInfo = entry.Value;
                        break;
                    }
                }

                double timestamp;
                if (!TryConvertDouble(GetReflectionMember(playerKitInfo, "cooldown"), out timestamp))
                    return 0.0;

                double remaining = timestamp - Facepunch.Math.Epoch.Current;
                return remaining > 0.0 ? remaining : 0.0;
            }
            catch (Exception ex)
            {
                PrintWarning("[InfoMenu] Ошибка получения cooldown IQKits: " + ex.Message);
                return 0.0;
            }
        }

        private string FormatCooldown(double seconds)
        {
            int total = Mathf.Max(1, Mathf.CeilToInt((float)seconds));
            int days = total / 86400;
            total %= 86400;
            int hours = total / 3600;
            total %= 3600;
            int minutes = total / 60;
            int secs = total % 60;

            if (days > 0)
                return string.Format(CultureInfo.InvariantCulture, "{0}д {1:00}ч {2:00}м", days, hours, minutes);
            if (hours > 0)
                return string.Format(CultureInfo.InvariantCulture, "{0}ч {1:00}м {2:00}с", hours, minutes, secs);
            if (minutes > 0)
                return string.Format(CultureInfo.InvariantCulture, "{0}м {1:00}с", minutes, secs);
            return string.Format(CultureInfo.InvariantCulture, "{0}с", secs);
        }

        private int GetKitPageCount(List<IQKitEntry> kits)
        {
            return kits == null || kits.Count == 0 ? 1 : Mathf.Max(1, Mathf.CeilToInt(kits.Count / 6f));
        }

        private void OpenKitsPage(BasePlayer player, int page)
        {
            if (player == null || !player.IsConnected)
                return;

            Plugin iq = GetIQKitsPlugin();
            List<IQKitEntry> kits = GetIQKits(player);
            int pageCount = GetKitPageCount(kits);
            page = Mathf.Clamp(page, 0, pageCount - 1);

            ClearPageContent(player);
            openKitPages[player.userID] = page;

            var container = new CuiElementContainer();
            string content = MainLayer + ".KitsContent";

            // Левая колонка создаётся один раз в OpenMenu().
            // Не удаляем её при открытии китов — иначе список кнопок исчезает.

            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0", FadeIn = 0.22f },
                RectTransform = { AnchorMin = "0.195 0.045", AnchorMax = "0.985 0.895" }
            }, MainLayer + ".Main", content);

            AddText(container, content, "КИТЫ", 25, TextAnchor.UpperLeft, config.TextColor,
                "0.03 0.86", "0.95 0.97", "Title");
            AddText(container, content, "НАБОРЫ IQKITS  •  ПОЛУЧИТЬ ДОСТУП К ОСТАЛЬНЫМ КИТАМ", 12,
                TextAnchor.UpperLeft, config.SecondaryTextColor, "0.032 0.80", "0.95 0.87", "Subtitle");

            container.Add(new CuiPanel
            {
                Image = { Color = ParseColor(config.GreenColor) },
                RectTransform = { AnchorMin = "0.03 0.775", AnchorMax = "0.30 0.782" }
            }, content);

            if (iq == null)
            {
                AddText(container, content,
                    "IQKits НЕ ЗАГРУЖЕН\n\nПлагин будет подключён автоматически после загрузки IQKits.",
                    16, TextAnchor.MiddleCenter, config.TextColor,
                    "0.10 0.35", "0.90 0.60", "NoPlugin");
            }
            else if (kits.Count == 0)
            {
                AddText(container, content,
                    "НАБОРЫ НЕ НАЙДЕНЫ\n\nПроверьте категории и права IQKits.",
                    16, TextAnchor.MiddleCenter, config.TextColor,
                    "0.10 0.35", "0.90 0.60", "NoKits");
            }
            else
            {
                int start = page * 6;
                int end = Mathf.Min(start + 6, kits.Count);

                for (int i = start; i < end; i++)
                {
                    int local = i - start;
                    int row = local / 2;
                    int col = local % 2;
                    float xMin = col == 0 ? 0.03f : 0.515f;
                    float xMax = col == 0 ? 0.485f : 0.97f;
                    float yMax = 0.72f - row * 0.18f;
                    float yMin = yMax - 0.15f;

                    IQKitEntry kit = kits[i];
                    string card = MainLayer + ".Kit." + i;
                    string statusKey = GetKitStatusKey(kit.Category, kit.Key);
                    double cooldown = GetKitRemainingCooldown(player, kit);
                    int usedAmount;
                    int maxAmount;
                    int kitType;
                    bool hasUsageLimit = TryGetKitUsageInfo(player, kit, out kitType, out usedAmount, out maxAmount);
                    bool kitEnded = hasUsageLimit && (kitType == 1 || kitType == 2) &&
                                    maxAmount > 0 && usedAmount >= maxAmount;
                    bool redeemed = GetRedeemedSet(player.userID).Contains(statusKey);
                    bool failed = GetFailedSet(player.userID).Contains(statusKey);
                    string inventoryFullKey;
                    bool inventoryFull = lastInventoryFullKit.TryGetValue(player.userID, out inventoryFullKey) &&
                                         string.Equals(inventoryFullKey, kit.Key, StringComparison.OrdinalIgnoreCase);

                    container.Add(new CuiPanel
                    {
                        Image = { Color = ParseColor(config.CardColor) },
                        RectTransform =
                        {
                            AnchorMin = string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###}", xMin, yMin),
                            AnchorMax = string.Format(CultureInfo.InvariantCulture, "{0:0.###} {1:0.###}", xMax, yMax)
                        }
                    }, content, card);

                    AddText(container, card, (string.IsNullOrWhiteSpace(kit.Title) ? kit.Key : kit.Title).ToUpperInvariant(),
                        16, TextAnchor.MiddleLeft, config.TextColor, "0.04 0.62", "0.96 0.86", "Name");
                    AddText(container, card, "КАТЕГОРИЯ: " + kit.CategoryTitle, 10, TextAnchor.MiddleLeft,
                        config.SecondaryTextColor, "0.04 0.43", "0.68 0.58", "Category");

                    bool isCopterKit = IsCopterKitKey(kit.Key);
                    PlayerData copterData = GetPlayerData(player);
                    bool copterAvailable = isCopterKit &&
                        ((copterData != null && copterData.PendingCopterKit) ||
                         permission.UserHasPermission(player.UserIDString, "iqkits.w5"));

                    if (isCopterKit)
                    {
                        // Пока покупка не забрана — показываем ВЗЯТЬ.
                        // После успешной выдачи permission iqkits.w5 и PendingCopterKit
                        // снимаются, поэтому здесь автоматически появляется МАГАЗИН.
                        container.Add(new CuiButton
                        {
                            Button =
                            {
                                Command = copterAvailable ? "infomenu.coptertake" : "infomenu.shop category 3",
                                // Кнопка МАГАЗИН у миникоптера должна быть такой же зелёной,
                                // как магазин у остальных китов.
                                Color = ParseColor(config.GreenColor),
                                HighlightedColor = ParseColor(config.ButtonHoverColor)
                            },
                            Text =
                            {
                                Text = copterAvailable ? "ВЗЯТЬ" : "МАГАЗИН",
                                Font = config.Font,
                                FontSize = 12,
                                Align = TextAnchor.MiddleCenter,
                                Color = "0 0 0 1"
                            },
                            RectTransform = { AnchorMin = "0.70 0.08", AnchorMax = "0.94 0.28" }
                        }, card);
                    }
                    else if (!kit.IsAllowed)
                    {
                        AddKitAccessButton(container, card);
                    }
                    else if (inventoryFull)
                    {
                        AddText(container, card, "ИНВЕНТАРЬ ПОЛОН", 11, TextAnchor.MiddleCenter, config.CloseColor,
                            "0.55 0.12", "0.98 0.31", "InventoryFull");
                    }
                    else if (kitEnded)
                    {
                        AddText(container, card, "КОНЧИЛСЯ", 11, TextAnchor.MiddleCenter, config.CloseColor,
                            "0.68 0.09", "0.96 0.30", "Ended");
                    }
                    else if (cooldown > 0.0)
                    {
                        AddKitCountdown(container, card, cooldown);
                    }
                    else if (failed)
                    {
                        AddKitAccessButton(container, card);
                    }
                    else
                    {
                        container.Add(new CuiButton
                        {
                            Button =
                            {
                                Command = string.Format(CultureInfo.InvariantCulture, "infomenu.kittake {0} {1}", i, page),
                                Color = ParseColor(config.GreenColor),
                                HighlightedColor = ParseColor(config.ButtonHoverColor)
                            },
                            Text = { Text = "ВЗЯТЬ", Font = config.Font, FontSize = 12,
                                Align = TextAnchor.MiddleCenter, Color = "0 0 0 1" },
                            RectTransform = { AnchorMin = "0.70 0.08", AnchorMax = "0.94 0.28" }
                        }, card);
                    }
                }
            }

            if (page > 0)
                AddPageButton(container, content, "‹", "infomenu.kits " + (page - 1), "0.03 0.015", "0.09 0.075");
            if (page < pageCount - 1)
                AddPageButton(container, content, "›", "infomenu.kits " + (page + 1), "0.91 0.015", "0.97 0.075");

            AddText(container, content, string.Format(CultureInfo.InvariantCulture, "{0} / {1}", page + 1, pageCount),
                11, TextAnchor.MiddleCenter, config.SecondaryTextColor, "0.40 0.015", "0.60 0.075", "Pages");

            CuiHelper.AddUi(player, container);
        }

        private void AddKitsSidebar(CuiElementContainer container, int page, string selectedCommand)
        {
            float top = 0.845f;
            const float height = 0.055f;
            const float gap = 0.014f;

            if (config == null || config.SideButtons == null)
                return;

            for (int i = 0; i < config.SideButtons.Count; i++)
            {
                SideButton button = config.SideButtons[i];
                if (button == null)
                    continue;

                float bottom = top - height;
                if (bottom < 0.045f)
                    break;

                bool selected = String.Equals(button.Command, selectedCommand, StringComparison.OrdinalIgnoreCase);
                string color = selected ? config.GreenColor : config.ButtonColor;
                string textColor = selected ? "0 0 0 1" : config.TextColor;

                container.Add(new CuiButton
                {
                    Button =
                    {
                        Command = $"infomenu.side {i}",
                        Color = ParseColor(color),
                        HighlightedColor = ParseColor(config.ButtonHoverColor)
                    },
                    Text =
                    {
                        Text = button.Title ?? "",
                        Font = config.Font,
                        FontSize = config.ButtonFontSize,
                        Align = TextAnchor.MiddleCenter,
                        Color = ParseColor(textColor)
                    },
                    RectTransform =
                    {
                        AnchorMin = $"0.055 {bottom:0.###}",
                        AnchorMax = $"0.945 {top:0.###}"
                    }
                }, MainLayer + ".Main.Side");

                top = bottom - gap;
            }
        }

