        #region Image / Text Helpers

        private string GetImage(string key)
        {
            if (ImageLibrary == null || string.IsNullOrEmpty(key))
                return null;

            return ImageLibrary.Call("GetImage", key) as string;
        }

        private const string GameStoreQrBase64 = "";

        private void DrawStoreQr(
            CuiElementContainer container,
            string parent,
            string anchorMin,
            string anchorMax,
            float alpha)
        {
            // Сначала используем реальный QR магазина из ImageLibrary.
            // Это именно QR: https://cdn.imagetourls.com/uploads/tyImg/X8qMgsxM.png
            string qrPng = null;

            if (ImageLibrary != null)
            {
                qrPng = ImageLibrary.Call("GetImage", ShopQrImageKey) as string;
            }

            // Если ImageLibrary ещё не успел скачать PNG, используем встроенный
            // резервный QR, чтобы в меню никогда не появлялся знак ?.
            if (string.IsNullOrEmpty(qrPng))
                qrPng = GameStoreQrBase64;

            if (string.IsNullOrEmpty(qrPng))
                return;

            container.Add(new CuiElement
            {
                Parent = parent,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = qrPng,
                        Color = $"1 1 1 {alpha.ToString("0.##", CultureInfo.InvariantCulture)}"
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0.5 0.21",
                        AnchorMax = "0.5 0.21",
                        OffsetMin = "-70 -70",
                        OffsetMax = "70 70"
                    }
                }
            });
        }

        private void DrawImage(
            CuiElementContainer container,
            string parent,
            string key,
            string anchorMin,
            string anchorMax,
            float alpha)
        {
            string png = GetImage(key);

            if (string.IsNullOrEmpty(png))
                return;

            container.Add(new CuiElement
            {
                Parent = parent,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = png,
                        Color = $"1 1 1 {alpha.ToString("0.##", CultureInfo.InvariantCulture)}"
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = anchorMin,
                        AnchorMax = anchorMax
                    }
                }
            });
        }

